      "title": "1945年のアラブ連盟",
      "body": [
        "第二次世界大戦中から<strong class=\"source-bold\">パレスチナには大量のユダヤ人が移住</strong>してきたから、周辺のアラブ諸国は「ユダヤ人の国ができるんじゃないか？」と警戒し、1945年3月、エジプトを中心に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アラブ連盟</strong></span> <strong class=\"source-bold\">【</strong>アラブ諸国連盟<strong class=\"source-bold\">】</strong>をつくったよ。"
      ],
