      "title": "原加盟国と北アフリカへの拡大",
      "body": [
        "加盟したのは、エ<strong class=\"source-bold\">ジプト・レバノン・シリア・イラク・トランスヨルダン</strong>（1949年以降はヨルダン＝ハーシム王国。ふつうヨルダンと呼ぶので、以下、ヨルダンと省略）<strong class=\"source-bold\">・サウジアラビア・イエメン</strong>で、のちにリビアやアルジェリアなど北アフリカのアラブ人国家も加わり、ユダヤ人国家<strong class=\"source-bold\">イスラエルの建国を阻止</strong>するために連携したよ。"
      ],
