      "body": [
        "そして、事態はどんどん深刻になる。大戦中に移住してきた<strong class=\"source-bold\">ユダヤ人</strong>と、現地にもともと住んでいたアラブ人（これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ人</strong></span>ね）の対立が激化し、各地で<strong class=\"source-bold\">アラブ人とユダヤ人の武力衝突</strong>が起こり始めた。"
      ],
