      "id": "modern-c05-l25-p01-041",
      "title": "1952年のエジプト革命",
      "body": [
        "そして1952年、<strong class=\"source-bold\">ナギブ</strong>や<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナセル</strong></span>を中心とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自由将校団</strong></span>は、軍事クーデタで<strong class=\"source-bold\">国王ファルーク【ファルーク1世】を追放</strong>し、ナギブを大統領とする共和政に移行した（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプト革命</strong></span>）。"
      ],
