      "title": "実施できなかったOPECの石油戦略",
      "body": [
        "アラブの産油国は、第3次中東戦争の時に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>OPEC<rt>オペック</rt></ruby></strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">石油輸出国機構</strong></span>】</strong>を結集して、「イスラエルに味方する国には、石油を売ってやんない」っていう石油戦略をやろうとしたんだけど、親米の国（イラン、ベネズエラ、インドネシアなど）の反対でできなかった。"
      ],
