      "id": "modern-c05-l25-p03-006",
      "title": "FLNの独立闘争とアルジェリア戦争",
      "body": [
        "これに対し、アルジェリアでは<strong class=\"source-bold\">民族解放戦線【FLN】</strong>が結成されて独立闘争を開始、壮絶な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルジェリア戦争</strong></span>が始まったよ。FLN は全国的なゲリラ戦を展開してフランス軍を苦しめ、<strong class=\"source-bold\">戦争の泥沼化でフランスの財政は傾き始めた</strong>。"
      ],
