      "title": "イギリス連邦からの離脱と共和国",
      "body": [
        "こうした批判に対し、さすがにイギリス連邦の中心であるイギリスも「そろそろ人種差別は見直したほうが……」と言ったら、南アフリカは「お前が始めたんだろ！」と反発。1961年、<strong class=\"source-bold\">アパルトヘイトを維持するためにイギリス連邦から離脱</strong>して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南アフリカ共和国</strong></span>になった。"
      ],
      "plainBody": [
        "こうした批判に対し、さすがにイギリス連邦の中心であるイギリスも「そろそろ人種差別は見直したほうが……」と言ったら、南アフリカは「お前が始めたんだろ！」と反発。1961年、アパルトヘイトを維持するためにイギリス連邦から離脱して、南アフリカ共和国になった。"
      ],
