export const sourcePages = {
  "454": "<h2>454</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第25回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">戦後の</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">西アジア・アフリカ</span></h1>\n<p>さて、アジアの戦後史の3回目、今回は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">西アジア</u>、そして<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アフリカ</u>を見ていくよ。大きなテーマは、いよいよ今回が最後だ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">大きくつかもう！</span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span></td></tr><tr><td><strong class=\"source-bold\">パレスチナ問題と中東戦争</strong></td><td><strong class=\"source-bold\">戦後の西アジア（イラン・イラク）</strong></td><td><strong class=\"source-bold\">戦後のアフリカ</strong></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">455〜464ページ</span></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">464〜468ページ</span></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">468〜475ページ</span></td></tr></tbody></table></div>\n<blockquote><p>現代まで続く中東問題はどうして起きたのか、じっくり見ていこうね！</p></blockquote>\n<p>現代の世界で、戦争が起きる可能性が高い地域の1つが<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">中東</u>だよ。戦後、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">イスラエル</u>が建国されてからもう半世紀以上も経ったのに、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">パレスチナ</u>をめぐる問題は解決の糸口がまるで見えない。しかも、<ruby>冷戦<rt>れいせん</rt></ruby>が終わってから、ますます状況が複雑になっている……。解決策はいったいどこにあるのかな？ まずは、現在の混迷の原因になっている<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">パレスチナ問題</u>を、じっくり解説していくね。</p>\n<p>さらに、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">イランとイラク</u>の問題や<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アフリカ諸国の独立</u>も、パレスチナ問題とあわせて確認してね。</p>\n<p>それじゃあ、戦後の西アジア・アフリカの始まり〜。</p>",
  "455": "<h2>455</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">パレスチナ問題と中東戦争</u></p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <span data-source-background=\"white\" data-source-border=\"red\" data-source-border-pattern=\"diagonal-lines\" style=\"border:1px solid #e52715;background:repeating-linear-gradient(135deg,#fff 0 4px,#fbe1e1 4px 5px);padding:0 0.2em\"><strong class=\"source-bold\">パレスチナ問題と中東戦争</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ パレスチナ問題はどうして起きたんだろう？</strong></span></h4>\n<p>現代まで続く中東の混乱は、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ</strong></span>」をめぐる問題が根底にあって、突き詰めると「<strong class=\"source-bold\">アラブ人 vs. イスラエル（ユダヤ人）</strong>」という対立に行き着いちゃう！。この対立の原因はなんだろう？ 19世紀末に「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シオニズム運動</strong></span>」が始まったけど、この時点でいきなりパレスチナに割り込んで「ユダヤ人の国をつくります〜」っていうのも無理だよね。だって、この時はアラブ人が普通に生活してるし。ただ、第一次世界大戦以降、中東をめぐる状況が変わり始めるんだ。</p>\n<p>第一次世界大戦に苦戦したイギリスは、オスマン帝国（トルコ）領内のアラブ人に、「オスマン帝国と戦ったら、<strong class=\"source-bold\">戦後のアラブ人の独立</strong>を認めましょう」っていう<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フセイン・マクマホン協定</strong></span>を結んだ。それなのに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サイクス・ピコ協定</strong></span>で、<strong class=\"source-bold\">英・仏・露でオスマン帝国領の分割</strong>を密約し、さらに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バルフォア宣言</strong></span>で<strong class=\"source-bold\">パレスチナでのユダヤ人国家（民族的郷土）建設</strong>まで約束した。同じ場所に3つの密約……こりゃ、絶対<ruby>揉<rt>も</rt></ruby>める。</p>\n<blockquote><p>英がイラク・トランスヨルダン・パレスチナ、仏がシリア・レバノンを委任統治領にしたよね</p></blockquote>\n<p>そして第一次世界大戦後、旧トルコ領のアラブ地域は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英仏の委任<ruby>統治<rt>とうち</rt></ruby>領</strong></span>になって、テキトーな国境が引かれ、<strong class=\"source-bold\">パレスチナはイギリスが管理</strong>することになった。ていうか、アラブ人は独立できない……。対するユダヤ人は……そんなに移住はしてこない。だって、各地にバラバラになってるけど、ユダヤ人たちだって、今の生活を捨ててまで「パレスチナに行こう」なんて、そうは思わないでしょ？ でも、ユダヤ人の生活を大きく変える事態が起きた！。それが「<strong class=\"source-bold\">ヒトラーのユダヤ人<ruby>迫害<rt>はくがい</rt></ruby></strong>」だよ。命の危険が迫ったユダヤ人の多くが迫害を逃れて<strong class=\"source-bold\">パレスチナへと移住</strong>し始め、<strong class=\"source-bold\">ユダヤ人の人口が急増</strong>したんだ（1914年には約8万5000人、イスラエルが建国された1948年にはなんと約65万人！）。ただ、<strong class=\"source-bold\"><ruby>亡命<rt>ぼうめい</rt></ruby>先として一番多かったのはアメリカ</strong>だ。アメリカに移住したユダヤ人は<strong class=\"source-bold\">経済界などで活躍</strong>したから、大きな影響を持つことになった。だから、このあとずっと「<strong class=\"source-bold\">アメリカはユダヤ人（ってことはイスラエル）支持</strong>」ってことになるんだ。現在の中東問題でも話題にあがる「アラブ人（イスラーム教徒）vs. アメリカ」っていう対立は、この時から始まったんだね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ イスラエルの建国をきっかけに、第1次中東戦争が始まった！</strong></span></h4>\n<p>第二次世界大戦中から<strong class=\"source-bold\">パレスチナには大量のユダヤ人が移住</strong>してきたから、周辺のアラブ諸国は「ユダヤ人の国ができるんじゃないか？」と警戒し、1945年3月、エジプトを中心に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アラブ連盟</strong></span> <strong class=\"source-bold\">【</strong>アラブ諸国連盟<strong class=\"source-bold\">】</strong>をつくったよ。加盟したのは、エ</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "456": "<h2>456</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第25回</strong></span> 戦後の西アジア・アフリカ</p></blockquote>\n<p><strong class=\"source-bold\">ジプト・レバノン・シリア・イラク・トランスヨルダン</strong>（1949年以降はヨルダン＝ハーシム王国。ふつうヨルダンと呼ぶので、以下、ヨルダンと省略）<strong class=\"source-bold\">・サウジアラビア・イエメン</strong>で、のちにリビアやアルジェリアなど北アフリカのアラブ人国家も加わり、ユダヤ人国家<strong class=\"source-bold\">イスラエルの建国を阻止</strong>するために連携したよ。ただ、アラブ連盟のなかがガッチリまとまってたわけじゃない。だって、この地域には王国が多く、<strong class=\"source-bold\">エジプトやヨルダンの国王は親英、サウジアラビア王は親米</strong>なんだもん。米・英がイスラエルを支持しているから、力ずくで<ruby>潰<rt>つぶ</rt></ruby>すわけにもいかなかったんだ。</p>\n<p>そして、事態はどんどん深刻になる。大戦中に移住してきた<strong class=\"source-bold\">ユダヤ人</strong>と、現地にもともと住んでいたアラブ人（これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ人</strong></span>ね）の対立が激化し、各地で<strong class=\"source-bold\">アラブ人とユダヤ人の武力衝突</strong>が起こり始めた。そして、怒りは委任<ruby>統治<rt>とうち</rt></ruby>をしているイギリスに向いた。「もはやパレスチナの事態はどうにもならん」と思った<strong class=\"source-bold\">イギリスは委任統治権を<ruby>放棄<rt>ほうき</rt></ruby></strong>して、問題の解決をすべてを国連に丸投げしちゃったんだよ。</p>\n<h3><span data-source-border=\"red-brown\" data-source-border-pattern=\"diagonal-lines\" style=\"border:4px solid #e52715;border-image:repeating-linear-gradient(135deg,#e52715 0 4px,#a43725 4px 8px) 4;padding:0 0.2em\"><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"background-color:#fbe1e1\"><strong class=\"source-bold\">中東戦争</strong></span></span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次中東戦争</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ戦争</strong></span>】</strong>［1948.5〜49］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>開戦と展開……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イスラエル建国</strong></span>を機に<strong class=\"source-bold\">アラブ側から開戦</strong>。米英はイスラエル支援</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>結果……<strong class=\"source-bold\">イスラエルの圧勝</strong>で<ruby>占領<rt>せんりょう</rt></ruby>地を拡大（<strong class=\"source-bold\">分割案の約1.5倍</strong>の領域を獲得）</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>アラブ側は、ヨルダンが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨルダン川西岸地区</strong></span>、エジプトが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ガザ地区</strong></span>を占領</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ難民</strong></span>が大量発生</p></blockquote>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次中東戦争</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スエズ戦争</strong></span>】</strong>［1956.10〜57.3］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>開戦と展開……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スエズ運河国有化</strong></span>に反発した<strong class=\"source-bold\">英仏とイスラエル</strong>が接近</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">イスラエルがエジプトを奇襲</strong>し、続いて<strong class=\"source-bold\">英仏軍が出兵</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">国連緊急総会</strong>で<strong class=\"source-bold\">米ソが協調</strong>して即時停戦を決議［1956.11］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>結果……<strong class=\"source-bold\">英仏・イスラエルの3国は撤退</strong>。エジプトは政治的に勝利</p></blockquote>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第3次中東戦争</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">6日間戦争</strong></span>】</strong>［1967.6］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>開戦と経過……<strong class=\"source-bold\">イスラエルがエジプトを奇襲攻撃</strong>し、イスラエルの一方的勝利</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>結果……<strong class=\"source-bold\">イスラエルの占領地が大幅に拡大</strong>（約5倍）、パレスチナ全土を支配</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>イスラエルが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シナイ半島・ガザ地区・ヨルダン川西岸地区・ゴラン高原</strong></span>を占領</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ難民</strong></span>の大量発生（一説には100万人以上）</p></blockquote>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第4次中東戦争</strong></span> <strong class=\"source-bold\">【</strong>十月戦争<strong class=\"source-bold\">】</strong>［1973.10］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>開戦と経過……<strong class=\"source-bold\">シナイ半島の回復を目指すエジプト</strong>が、シリアと連合して開戦</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span>緒戦は<strong class=\"source-bold\">イスラエルに勝利</strong>したが、<strong class=\"source-bold\">イスラエルが反撃</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アラブ石油輸出国機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>OAPEC<rt>オアペック</rt></ruby></strong></span>】</strong>が「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">石油戦略</strong></span>」を発動［1973］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次石油危機</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オイル＝ショック</strong></span>】</strong>が発生［1973］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>結果……イスラエルは<strong class=\"source-bold\">戦闘には勝利</strong>したが<strong class=\"source-bold\">政治的に敗北</strong>し、不敗神話が崩壊</p></blockquote>",
  "457": "<h2>457</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">パレスチナ問題と中東戦争</u></p></blockquote>\n<p>こうして1947年、国連総会で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ分割案</strong></span>が決まり、パレスチナは<strong class=\"source-bold\">ユダヤ人国家とアラブ人国家に2分割</strong>、キリスト教・ユダヤ教・イスラーム教の聖地が集まる<strong class=\"source-bold\">イェルサレムは国際管理下</strong>に置くことになった。ただ、この分割案にはむちゃくちゃな問題がある。だって、多数派のアラブ人（約3分の2だよ）に割り当てられた土地は約4割！、<strong class=\"source-bold\">少数派のユダヤ人のほうが多くの土地をもらう</strong>ことになったんだもん。いくら<strong class=\"source-bold\">米英の強い支持</strong>があるといっても、もともとの居住者は「アラブ人」でしょ（ユダヤ人がパレスチナにいたのは「ローマ帝国時代」までだ）。アラブ人が怒るのは当然だ。そして、分割案を受け入れたユダヤ人が1948年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イスラエル</strong></span>を建国すると、分割案を拒否して<strong class=\"source-bold\">イスラエルの建国を認めないアラブ連盟から開戦</strong>に踏み切り、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次中東戦争</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ戦争</strong></span>】</strong>が始まったんだ。</p>\n<h4><strong class=\"source-bold\">〈第1次中東戦争〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"black\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">アラブ連盟</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">↔</strong></span></td><td><span data-source-border=\"red\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #e52715;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">イスラエル</strong></span></td><td><span data-source-color=\"black\" style=\"color:#001000\">━</span></td><td><span data-source-border=\"red\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #e52715;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">アメリカ</strong></span><br><span data-source-border=\"red\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #e52715;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">イギリス</strong></span></td></tr><tr><td>国王は親英・親米</td><td><span data-source-color=\"brown\" data-source-line-style=\"dashed\" style=\"color:#a43725;border-bottom:1px dashed #a43725\">┄</span></td><td></td><td></td><td></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">トルコ</strong></td><td><strong class=\"source-bold\">レバノン</strong></td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">シリア</strong></span></td><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">イラク</strong></span></td></tr><tr><td><strong class=\"source-bold\">クウェート</strong></td><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">ヨルダン</strong></span></td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">サウジアラビア</strong></span></td><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">エジプト</strong></span></td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">カタール</strong></span></td><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">オマーン</strong></span></td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">イエメン</strong></span></td><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">スエズ運河</strong></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">パレスチナ</strong><br>→<span data-source-color=\"red\" style=\"color:#e52715\">イスラエル</span>建国</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">パレスチナの拡大図がこちら！</span><span data-source-color=\"red\" style=\"color:#e52715\">↗</span></td></tr><tr><td><span data-source-color=\"gray-green\" data-source-marker=\"area\" style=\"color:#8d977f\">■</span></td><td>アラブ連盟の原加盟国</td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td><strong class=\"source-bold\">〈パレスチナ分割案〉</strong></td><td><strong class=\"source-bold\">〈第1次中東戦争後〉</strong></td></tr><tr><td><strong class=\"source-bold\">レバノン</strong></td><td><strong class=\"source-bold\">レバノン</strong></td></tr><tr><td><strong class=\"source-bold\">シリア</strong></td><td><strong class=\"source-bold\">シリア</strong></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">アラブ人国家</span></td><td>ガザ地区</td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">ユダヤ人国家</span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\">ヨルダン川西岸地区</span></td></tr><tr><td><strong class=\"source-bold\">ヨルダン</strong></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イスラエル</strong></span></span></td></tr><tr><td><strong class=\"source-bold\">エジプト</strong></td><td><strong class=\"source-bold\">ヨルダン</strong></td></tr><tr><td><strong class=\"source-bold\">サウジアラビア</strong></td><td><strong class=\"source-bold\">エジプト</strong></td></tr><tr><td><span data-source-color=\"red\" data-source-marker=\"hatch\" data-source-pattern=\"vertical-lines\" style=\"color:#e52715\">▥</span> <span data-source-color=\"green\" data-source-marker=\"hatch\" data-source-pattern=\"horizontal-lines\" style=\"color:#859476\">▤</span></td><td><strong class=\"source-bold\">サウジアラビア</strong><br><span data-source-color=\"red\" data-source-marker=\"hatch\" data-source-pattern=\"vertical-lines\" style=\"color:#e52715\">▥</span> <span data-source-color=\"green\" data-source-marker=\"hatch\" data-source-pattern=\"horizontal-lines\" style=\"color:#859476\">▤</span></td></tr></tbody></table></div>\n<p>開戦してみると、米英の支援を受けた<strong class=\"source-bold\">イスラエルが圧勝</strong>した。ていうか、<strong class=\"source-bold\">アラブ連盟は自滅</strong>したようなもんだ。武器や食糧も不足していたし、親米・親英の国王が多いから作戦もまとまらず、最後はバラバラになったんだもん。そして、国連の停戦調停が成立すると、気づけば<strong class=\"source-bold\">イスラエルが分割案の約1.5倍の領域を獲得</strong>していた。対するアラブ側では、ヨルダンが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨルダン川西岸地区</strong></span>、エジプトが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ガザ地</strong></span></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "458": "<h2>458</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第25回</strong></span> 戦後の西アジア・アフリカ</p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">区</strong></span>を占領、だからパレスチナ問題は<strong class=\"source-bold\">アラブ諸国（特にエジプト）とイスラエルの対立</strong>に変わったんだ。そして一番困ったのは、戦争で行き場を失った100万人以上（人数は諸説ある）の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ難民</strong></span>（もともとパレスチナに住んでいたアラブ人）だよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ エジプト革命で親英の王政を打倒！ ナセルは非同盟主義へ</strong></span></h4>\n<p>パレスチナ戦争に完敗したことで、アラブ諸国、特に<strong class=\"source-bold\">エジプト</strong>では、親英の国王ファルーク1世に対し、「なんでイスラエルを支援するイギリスと手を切らないんだ」という不満が高まった。<strong class=\"source-bold\">ナセルをはじめとする軍の若い将校たち</strong>は、「こんな貧弱な軍隊では、イスラエルにみじめな敗北を続けるだけだ！」と怒り、秘密結社の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自由将校団</strong></span>をつくって、王政打倒のチャンスをうかがっていた。</p>\n<blockquote><p>ついにナセルが登場！ イギリスと手を切るには、王政ごと倒す</p></blockquote>\n<p>こうした不満をそらすため、エジプト政府（この時の政権はワフド党）は、イギリスのスエズ運河地帯への駐兵権を認める<strong class=\"source-bold\">エジプト＝イギリス同盟条約を一方的に<ruby>破棄<rt>はき</rt></ruby></strong>した。ただ、イギリスが認めたわけじゃないから、スエズ運河地帯ではイギリス軍とエジプト軍が衝突！。エジプト国内は大混乱となり、いよいよ無政府状態になった。</p>\n<p>そして1952年、<strong class=\"source-bold\">ナギブ</strong>や<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナセル</strong></span>を中心とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自由将校団</strong></span>は、軍事クーデタで<strong class=\"source-bold\">国王ファルーク【ファルーク1世】を追放</strong>し、ナギブを大統領とする共和政に移行した（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプト革命</strong></span>）。彼らは、事実上の植民地状態にあるエジプトを「ちゃんと独立」させて、<strong class=\"source-bold\">イギリスが操っていた国王や大地主階級たちを倒そう</strong>としたんだね。その後、大統領となったナギブとナセルが議会政治への復帰や土地改革の問題をめぐって対立すると、軍部の支持をまとめた<strong class=\"source-bold\">ナセルがナギブを追放</strong>して権力を握り、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナセル</strong></span><strong class=\"source-bold\">は国民投票で大統領</strong>になった。そして、ナセルに大きな影響を与えたのが、1955年の<strong class=\"source-bold\">第1回アジア・アフリカ会議【バンドン会議】</strong>だよ。</p>\n<p><strong class=\"source-bold\">バンドン会議</strong>でインドのネルーやインドネシアのスカルノらと交流したナセルは、「<strong class=\"source-bold\">非同盟主義</strong>」に強く影響を受けて<strong class=\"source-bold\">積極的な中立外交</strong>へと向かい、1955年には反共軍事同盟である<strong class=\"source-bold\">バグダード条約機構への加盟を拒否</strong>した。だって、イスラエルを支援する米英側の同盟に入るなんてありえない！</p>\n<p>エジプトの中立外交に<ruby>慌<rt>あわ</rt></ruby>てたイギリスは、エジプトが計画していた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アスワン＝ハイダム</strong></span>の建設を支援することで、エジプトを西側陣営につなぎとめようとしたんだ。まあ、ダム建設を助けてくれるのはいいんだけど、ナセルにはもっと緊急の問題があった。それは<strong class=\"source-bold\">ガザ地区へのイスラエルの攻撃</strong>だよ。ガザは当時パレスチナ・ゲリラの基地になっていたからね。「とにかく軍備の増強を急げ」と思ったナセルは、共産圏（ソ連側）のチェコスロヴァキアから武器を買ったんだ。そしたらア</p>",
  "459": "<h2>459</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">パレスチナ問題と中東戦争</u></p></blockquote>\n<p>メリカが怒った！ そりゃ、<ruby>冷戦<rt>れいせん</rt></ruby>の時代だもんね。<strong class=\"source-bold\">エジプトのソ連への接近</strong>にいらだった米英は、<strong class=\"source-bold\">アスワン＝ハイダムの建設資金融資を撤回</strong>したんだ。</p>\n<p>反発したナセルは、「それならば、建設資金はエジプトでつくる！」とばかりに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スエズ運河国有化</strong></span>を宣言、スエズ運河の通航料をダムの建設資金にあてることにした。これに対し、スエズ運河の株式を持つ<strong class=\"source-bold\">英仏両国が激しく反発</strong>。スエズ運河からの収入に加えて、イギリスは「ヨーロッパへの石油輸送をおさえて、<strong class=\"source-bold\">中東での<ruby>覇権<rt>はけん</rt></ruby>を維持したい</strong>」って考え、フランスも「<strong class=\"source-bold\">アルジェリア独立を支援するエジプト</strong>は、いつか<ruby>潰<rt>つぶ</rt></ruby>してやる！」と思っていたからね。そして、エジプトを攻撃するチャンスを待っていた<strong class=\"source-bold\">イスラエルが、英仏2国に乗っかった</strong>んだ！</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 第2次中東戦争の影響で、アラブ民族主義が盛り上がった！</strong></span></h4>\n<p>こうして1956年、<strong class=\"source-bold\">イスラエル軍がエジプトを奇襲</strong>し、続いて<strong class=\"source-bold\">英仏軍が出兵</strong>して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次中東戦争</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スエズ戦争</strong></span>】</strong>が<ruby>勃発<rt>ぼっぱつ</rt></ruby>したよ。ただ、この戦争は英仏の思いどおりにはならない。イギリスは「アメリカは当然支持してくれるはず」って期待してたのに、<strong class=\"source-bold\">アメリカは英仏を支援しなかった</strong>。だって、アジア・アフリカ諸国が国連で「英仏は撤退しろ」と言い始めたんだもん。これは<strong class=\"source-bold\">バンドン会議の影響</strong>だよ！ すでに<strong class=\"source-bold\">ソ連はエジプトを支持</strong>していたから、アメリカが英仏を支持したら、アジア・アフリカ諸国がみんなソ連にくっついて社会主義になっちゃうよ。</p>\n<p>こうして<strong class=\"source-bold\">国連緊急総会</strong>では<strong class=\"source-bold\">米ソが協調して即時停戦を決議</strong>し、アメリカ（アイゼンハワー政権）も英仏に全く支援をしなかったから、<strong class=\"source-bold\">英仏・イスラエルは完全に孤立して撤退</strong>するしかなかった。そしてイギリスでは、出兵の責任を問われた<strong class=\"source-bold\">イーデン内閣が総辞職</strong>に追い込まれたんだ。でも、ここでも一番困ったのは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ難民</strong></span>だよ……。新たに70万人もの難民が発生したんだもん！。</p>\n<p>英仏を撤退に追い込んだから、<strong class=\"source-bold\">政治的にはエジプトの勝ち</strong>だね。<strong class=\"source-bold\">ナセルはアラブ民族主義（アラブ＝ナショナリズム）のリーダー</strong>となり、アラブ人の連携（<strong class=\"source-bold\">パン＝アラブ主義</strong>）を掲げて「反イスラエル・反米英」を主張したんだ。</p>\n<p>アラブ民族主義を実現するため、ナセルはエジプトとシリアを合併して<strong class=\"source-bold\">アラブ連合共和国</strong>をつくった。とはいっても、ナセルが大統領だから主導権はエジプトだね。そして、<strong class=\"source-bold\">ソ連に接近</strong>して計画経済と大企業の国有化を進め、ソ連の援助と技術協力でアスワン＝ハイダムの建設を始めたんだ（完成は1970年）。</p>\n<blockquote><p>アラブ民族主義がソ連と接近したから、パレスチナ問題は冷戦に組み込まれたんだよ……</p></blockquote>\n<p>さらに、ナセルの影響を受けた周辺諸国でも<strong class=\"source-bold\">アラブ民族主義</strong>が盛り上がったんだけど、これって結局「<strong class=\"source-bold\">反英仏</strong>」だよ。1958年、<strong class=\"source-bold\">レバノン</strong>では<strong class=\"source-bold\">イスラーム教徒とキリスト教徒（マロン派）の対立</strong>から各地で暴動が起こり、親西欧（特にフランス）のキリスト教徒の政権が危機になった（<strong class=\"source-bold\">レバ</strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "460": "<h2>460</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第25回</strong></span> 戦後の西アジア・アフリカ</p></blockquote>\n<p><strong class=\"source-bold\">ノン暴動</strong>）。さらにイラクでも、<strong class=\"source-bold\">カセム</strong>らが親英の王政を倒す<strong class=\"source-bold\">イラク革命</strong>が起こったんだ。</p>\n<p>こうしたアラブの動きを見たアメリカ大統領アイゼンハワーは、「このままでは中東が社会主義になる」と焦ったんだ。だって<ruby>冷戦<rt>れいせん</rt></ruby>の時代だから、「<strong class=\"source-bold\">反英仏＝反米＝親ソ連</strong>」につながるからね。そこで「英仏にかわってアメリカが中東防衛のために軍を派遣する」という<strong class=\"source-bold\">アイゼンハワー＝ドクトリン</strong>を発表すると、1958年には<strong class=\"source-bold\">レバノンに出兵</strong>し、これにあわせてイギリスも<strong class=\"source-bold\">ヨルダンに出兵</strong>したんだ。しかし、国連での非難は避けられなかった。国連総会ではアジア・アフリカ諸国の支持で<strong class=\"source-bold\">アラブ10カ国決議案</strong>が議決され、米英軍は撤退するしかなくなったんだよ。</p>\n<p>第2次中東戦争やイラク革命によって、<strong class=\"source-bold\">イギリスが中東情勢に力を持たないことがはっきり</strong>したね。これは、19世紀から続いていた「<strong class=\"source-bold\">パクス＝ブリタニカ」が完全に終わった</strong>ってことだ。以後、パレスチナ問題は冷戦と結びつき、「<strong class=\"source-bold\">イスラエル＝アメリカ vs. アラブ＝ソ連</strong>」という新たな段階に入ってしまったんだ。</p>\n<h4><strong class=\"source-bold\">〈パレスチナ問題の対立（第2次中東戦争後）〉</strong></h4>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">冷戦</strong></span><span data-source-color=\"red\" style=\"color:#e52715\">↔</span></p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"green\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #89967b;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">アメリカ</strong></span></td><td>支援<span data-source-color=\"green\" style=\"color:#315837\">━</span></td><td><span data-source-border=\"green\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #89967b;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">イスラエル</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中東戦争</strong></span><span data-source-color=\"red\" style=\"color:#e52715\">↔</span></td><td><span data-source-border=\"brown\" data-source-border-style=\"dashed\" style=\"border:1px dashed #a43725;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">アラブ連盟</strong><br><span data-source-border=\"brown\" data-source-border-width=\"thick\" style=\"border:3px solid #a43725;padding:0 0.2em\"><strong class=\"source-bold\">エジプト</strong></span><br><span data-source-color=\"black\" data-source-marker=\"outline-arrow\" style=\"color:#001000\">⇩</span>影響<br><strong class=\"source-bold\">アラブ民族主義</strong><br><strong class=\"source-bold\">→社会主義に接近</strong></span></td><td><span data-source-color=\"brown\" style=\"color:#a43725\">━</span>支援</td><td><span data-source-border=\"brown\" data-source-border-width=\"thick\" style=\"border:3px solid #a43725;padding:0 0.2em\"><strong class=\"source-bold\">ソ連</strong></span></td></tr><tr><td></td><td>支援<span data-source-color=\"green\" style=\"color:#315837\">━</span></td><td><span data-source-border=\"green\" data-source-border-style=\"dashed\" style=\"border:1px dashed #89967b;border-radius:0.2em;padding:0 0.2em\"><span data-source-border=\"green\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #89967b;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">イギリス</strong></span><br><span data-source-border=\"green\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #89967b;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">イラン</strong></span><br><span data-source-border=\"green\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #89967b;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">トルコ</strong></span><br><span data-source-border=\"green\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #89967b;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">パキスタン</strong></span><br><strong class=\"source-bold\">バグダード条約機構</strong></span></td><td></td><td><span data-source-border=\"black\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">アジア・アフリカ諸国</strong></span><span data-source-color=\"black\" data-source-marker=\"curved-line\" style=\"color:#001000\">⌒</span>支持</td><td></td><td></td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ イスラエルがエジプトを奇襲！ 第3次中東戦争はイスラエルの圧勝！</strong></span></h4>\n<p>ここでちょっと思い出してほしいんだけど、パレスチナ問題って、本来は「<strong class=\"source-bold\">パレスチナ人 vs. イスラエル</strong>」の対立だよね。それがいつの間にか「<strong class=\"source-bold\">アラブ諸国（エジプトやシリアなど）vs. イスラエル</strong>」の対立にかわり、さらに<strong class=\"source-bold\">米ソの冷戦</strong>にまで結びついた。パレスチナ人は「オレたちのことを忘れるな」って思ったんだよ。こうして1964年、<strong class=\"source-bold\">エジプトの支援を受けたパレスチナ人</strong>が土地と権利の回復を目指して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ解放機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">PLO</strong></span>】</strong>をつくった。とはいっても、イスラエルに真っ向勝負できる軍隊なんてないから、<strong class=\"source-bold\">ゲリラ活動でイスラエルを攻撃</strong>したんだ。すると<strong class=\"source-bold\">イスラエルがこれに<ruby>報復<rt>ほうふく</rt></ruby></strong>、さらにパレスチナを支援する<strong class=\"source-bold\">シリア軍とイスラエル軍の衝突事件</strong>がたびたび起きるようになった。</p>",
  "461": "<h2>461</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">パレスチナ問題と中東戦争</u></p></blockquote>\n<p>そこで、1961年にアラブ連合共和国を解消していた<strong class=\"source-bold\">シリアとエジプト</strong>は、再び共同防衛条約を結んだよ。そしてインド洋への出口を確保しようと<ruby>紅海<rt>こうかい</rt></ruby>への進出を始めたイスラエルに対し、<strong class=\"source-bold\">エジプトはアカバ湾を<ruby>封鎖<rt>ふうさ</rt></ruby></strong>して対抗した。しかも、イスラエルを支援するアメリカは、ベトナム戦争で手一杯だ……。この隙にソ連がどんどん武器を支援して、アラブ側はすでにイスラエルの2倍近い軍備を持っている。焦ったイスラエルは「攻撃は最大の防御！」とばかりに反撃に出たんだ。</p>\n<p>1967年6月5日の朝、<strong class=\"source-bold\">イスラエルはエジプトに奇襲攻撃</strong>をかけた！。早朝にエジプトの空軍基地を奇襲すると、午後にはシリア・ヨルダンも攻撃、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第3次中東戦争</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">6日間戦争</strong></span>】</strong>が始まった。そして、わずか6日間で、イスラエルは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シナイ半島</strong></span>・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ガザ地区</strong></span>（エジプト占領下）・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨルダン川西岸地区</strong></span>（ヨルダン占領下）・<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴラン高原</strong></span>（シリア領）を占領、占領地を5倍に拡大して<strong class=\"source-bold\">パレスチナ全土を支配下に置いた</strong>んだ。</p>\n<h4><strong class=\"source-bold\">〈第3次中東戦争後〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">レバノン</strong></td><td>ゴラン高原</td></tr><tr><td><strong class=\"source-bold\">シリア</strong></td><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\">ヨルダン川西岸地区</span></td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\">ガザ地区</span></td><td><em>スエズ運河</em></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イスラエル</strong></span></span></td><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><em>シナイ半島</em></span></td></tr><tr><td><strong class=\"source-bold\">ヨルダン</strong></td><td><strong class=\"source-bold\">エジプト</strong></td></tr><tr><td><strong class=\"source-bold\">サウジアラビア</strong></td><td><span data-source-color=\"red\" data-source-marker=\"hatch\" data-source-pattern=\"vertical-lines\" style=\"color:#e52715\">▥</span></td></tr><tr><td><span data-source-color=\"pink\" data-source-marker=\"area\" style=\"color:#f8dede\">■</span></td><td>戦後のイスラエルの占領地</td></tr></tbody></table></div>\n<p>実はこの作戦のために、イスラエルはイラク空軍にスパイを送り込んで、エジプトが持っているのと同じソ連製のミグ21戦闘機を盗んだり、エジプトやシリアの軍事施設の正確な地図まで手に入れたりしたんだって！。そりゃ圧勝もするよ。</p>\n<p>この戦争で増えてしまった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ難民</strong></span>は、一説には新たに100万人以上ともいわれている。さらに、エジプトにとっては「<strong class=\"source-bold\">スエズ運河の<ruby>閉鎖<rt>へいさ</rt></ruby></strong>」が最も重大な問題になったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ アラブ諸国は「石油」で、PLOは「ゲリラ」で、イスラエルに対抗</strong></span></h4>\n<p>あまりにもあっけない負け方で、<strong class=\"source-bold\">アラブでのナセルの威信は大きく傷ついた</strong>。しかも、ソ連製の武器がイスラエルにまるで対抗できなかったので、アラブ諸国は別の対抗策を考え始めたんだ。それが「石油」だよ。アラブの産油国は、第3次中東戦争の時に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>OPEC<rt>オペック</rt></ruby></strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">石油輸出国機構</strong></span>】</strong>を結集して、「イスラエルに味方する国には、石油を売ってやんない」っていう石油戦略をやろうとしたんだけど、親米の国（イラン、ベネズエラ、インドネシアなど）の反対でできなかった。「だったら、アラブだけでやればいい！」と考えた<strong class=\"source-bold\">反イスラエルのアラブ産油国（サウジアラビア・クウェート・リビア）</strong>は、1968年<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アラブ石油輸出国機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>OAPEC<rt>オアペック</rt></ruby></strong></span>】</strong>を結成し、のちに周辺のアラブ諸国をこれに巻き込んだ。さらに<strong class=\"source-bold\">PLOでもナセルの影</strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "462": "<h2>462</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第25回</strong></span> 戦後の西アジア・アフリカ</p></blockquote>\n<p><strong class=\"source-bold\">響力が弱まり</strong>、より過激な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アラファト</strong></span>が議長に就任、ゲリラによる武装闘争を激化させると、なんとヨルダンの政権を奪おうとする事件まで起きたんだ。そして1970年、PLOとアラブ諸国の調停を進めようとした<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナセルが急死</strong></span>すると、PLOはエジプトからも離れて、レバノンのベイルートを根拠地にテロ攻撃やゲリラ戦を続けたんだ！。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 第4次中東戦争は石油でアラブが勝利！ でも、シナイ半島は還ってこない……</strong></span></h4>\n<p>ナセルの死後、副大統領から昇格して大統領となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サダト</strong></span>は、<strong class=\"source-bold\">イスラエルからシナイ半島を取り返す</strong>ために強硬路線をとったよ。だって、このままじゃ、スエズ運河は封鎖されたままだ。こうなったら、第3次中東戦争の<ruby>復讐<rt>ふくしゅう</rt></ruby>だ！ まずは、1971年にシリア、リビアと連合して<strong class=\"source-bold\">アラブ共和国連邦</strong>をつくり、<strong class=\"source-bold\">イスラエルを包囲</strong>した。さらにエジプトには強力なスポンサーが現れたんだ！ 資源ナショナリズムを強めて石油で<ruby>莫大<rt>ばくだい</rt></ruby>な資金を手にした<strong class=\"source-bold\">サウジアラビア</strong>が、反イスラエルってことでサダトに資金を援助、エジプトはリビア経由で軍備を強化した。だって、もはやソ連があてにならないことがわかったでしょ。あとは「目には目を、歯には歯を、奇襲には奇襲攻撃」だよ。</p>\n<p>こうして1973年10月、<strong class=\"source-bold\">エジプト・シリア連合軍がイスラエルに奇襲攻撃</strong>を仕掛け、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第4次中東戦争</strong></span>が始まった。戦闘は、最初はエジプトが優勢だったけど、少しずつイスラエルが反撃し始めて、エジプトは劣勢になった。最後は、アメリカが「どちらもいい加減にしろ！」と両国に圧力をかけたので、双方が<strong class=\"source-bold\">国連<ruby>安保理<rt>あんぽり</rt></ruby>の停戦決議を受け入れて停戦</strong>したんだ。</p>\n<p>でも、これだけでは終わらなかったんだよ。ついに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アラブ石油輸出国機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>OAPEC<rt>オアペック</rt></ruby></strong></span>】</strong>が「<strong class=\"source-bold\">イスラエルの味方には石油を売らない！</strong>」という<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">石油戦略</strong></span>を発動したんだ！ <strong class=\"source-bold\">石油減産</strong>と<strong class=\"source-bold\">親イスラエル国（米・西欧・日など）への石油禁輸</strong>、さらに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>OPEC<rt>オペック</rt></ruby></strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">石油輸出国機構</strong></span>】</strong>も<strong class=\"source-bold\">石油価格の引き上げ</strong>を決めたから、石油価格は1年前の約4倍にまで急騰！ 西側先進国の経済を直撃して、世界は深刻な<ruby>不況<rt>ふきょう</rt></ruby>になったんだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次石油危機</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オイル＝ショック</strong></span>】</strong>だよ。日本では、政府が世界中から石油を買い<ruby>漁<rt>あさ</rt></ruby>り、庶民はトイレットペーパーを買い漁った。だって、「トイレットペーパーがなくなる！」ってデマが広がったんだもん。こうして第4次中東戦争は完全に「石油」の勝利になって、<strong class=\"source-bold\">イスラエルは「政治的」に敗北</strong>、ついに不敗神話が崩壊したんだよ。</p>\n<blockquote><p>石油は強力な武器になった！ でも……エジプトはシナイ半島を取り返せなかったね</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 中東問題の転機。エジプト＝イスラエル平和条約が結ばれた！</strong></span></h4>\n<p>第4次中東戦争が終わって、中東問題は大きな転機を迎えるよ。まず、国連では</p>",
  "463": "<h2>463</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">パレスチナ問題と中東戦争</u></p></blockquote>\n<p><strong class=\"source-bold\">PLOが国連総会にオブザーバーとして参加</strong>し、総会で<strong class=\"source-bold\">パレスチナ人の民族<ruby>自決<rt>じけつ</rt></ruby>権</strong>が認められた。これは、パレスチナが「国家」として認められるための第一歩だよ。さらに、反イスラエルの中心にいるエジプトと、イスラエルの国内にも大きな変化が生まれていたんだ。</p>\n<p>エジプトでは、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サダト</strong></span>が「このまま<strong class=\"source-bold\">イスラエルと対立を続けてもシナイ半島を取り返すのはムリ</strong>だ」と考えていた。だって、エジプトはイスラエルに戦闘で勝ったことがない。第4次中東戦争は、確かに「石油」で勝ったけど、石油がたいして採れないエジプトはまるで得をしてない。サダトは「<strong class=\"source-bold\">シナイ半島の返還を条件に、イスラエルと和解</strong>したほうが得だ」と思ったんだ。さらにアメリカとも和解して、戦費で<ruby>疲弊<rt>ひへい</rt></ruby>したエジプト経済を立て直したかったんだね。</p>\n<p>一方、イスラエルも似たような状況だよ。だって、<strong class=\"source-bold\">第4次中東戦争の戦費が国家予算の1.5倍</strong>！ 首相の<strong class=\"source-bold\">ベギン</strong>は右派連合 <strong class=\"source-bold\">【</strong>リクード<strong class=\"source-bold\">】</strong>政権だから本来は強硬派だけど、財政難でこれ以上戦争を続けるのは厳しい。そして、アメリカ大統領は「<strong class=\"source-bold\">人権外交</strong>」のカーターだったから「話せばわかる」って、エジプトとイスラエルの<ruby>仲介<rt>ちゅうかい</rt></ruby>に入ったんだ。</p>\n<p>こうして1977年、<strong class=\"source-bold\">サダトがイスラエルを訪問</strong>して和平交渉を進める意思を伝え、翌年、両国はアメリカのキャンプ＝デーヴィッドで会談すると、<strong class=\"source-bold\">国交正常化とシナイ半島返還に合意</strong>した（<strong class=\"source-bold\">キャンプ＝デーヴィッド合意</strong>）。そして1979年、エジプト大統領<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サダト</strong></span>とイスラエル首相<strong class=\"source-bold\">ベギン</strong>が、アメリカ大統領<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カーター</strong></span>の仲介で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプト＝イスラエル平和条約</strong></span>に調印、イスラエルは正式に<strong class=\"source-bold\">シナイ半島を返還</strong>し（軍の撤退完了は1982年）、<strong class=\"source-bold\">エジプトはアラブ諸国で初めてイスラエルを承認してアラブ連盟を脱退</strong>したんだ。</p>\n<p>これを見たアラブ諸国とPLOは、「サダトがパン＝アラブ主義をぶち壊した」と怒って<strong class=\"source-bold\">エジプトと断交</strong>、さらに和平に反対する<strong class=\"source-bold\">イスラーム原理主義者</strong>（ムスリム<ruby>同胞団<rt>どうほうだん</rt></ruby>といわれている）が<strong class=\"source-bold\">サダトを暗殺</strong>した！。ただ、後任の大統領となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムバラク</strong></span>も、サダトの路線を継承して<strong class=\"source-bold\">親米・親イスラエル路線</strong>をとりつつ、経済再建に努めたんだよ。</p>\n<p>一方のイスラエルは、「もはやエジプトが攻めてくることはないから、PLOを<ruby>潰<rt>つぶ</rt></ruby>してやる！」として、<strong class=\"source-bold\">PLOの本拠地</strong>がある<strong class=\"source-bold\">レバノンに<ruby>侵攻<rt>しんこう</rt></ruby></strong>したんだ。レバノンはもともと、西欧寄りのキリスト教（マロン派）政権とイスラーム教徒の対立を抱えていたから、イスラエルの侵攻で内戦状態となり、ベイルート<ruby>虐殺<rt>ぎゃくさつ</rt></ruby>事件（マロン派キリスト教徒によるパレスチナ難民の大虐殺）も起こった。追いつめられたPLOは、<strong class=\"source-bold\">イスラエルが<ruby>占領<rt>せんりょう</rt></ruby>する地域での民衆の抗議行動（インティファーダ）</strong>を組織するくらいしか、抵抗の手段がなくなっちゃった。でも、インティファー</p>\n<blockquote><p>サダト暗殺で大統領になったムバラクは、2011年の「アラブの春」まで<ruby>独<rt>どく</rt></ruby><ruby>裁<rt>さい</rt></ruby>を続けるよ</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "464": "<h2>464</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第25回</strong></span> 戦後の西アジア・アフリカ</p></blockquote>\n<p>ダって集団で「石を投げる」くらいしかできなかったんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ <ruby>冷戦<rt>れいせん</rt></ruby>終結で中東和平が前進！ でも、長年の対立は簡単には消えないよ</strong></span></h4>\n<p>冷戦が終わって米ソが協調したから、1991年にはこれまで実現しなかった「<strong class=\"source-bold\">イスラエルと周辺アラブ諸国、PLO</strong>」のすべてが参加する<strong class=\"source-bold\">中東和平会議【マドリード会議】</strong>が開かれた。「これでパレスチナ問題が大きく前進するのでは……」と期待されたんだけど、この年の12月にソ連が崩壊しちゃったんだ。それでも<strong class=\"source-bold\">ノルウェーの<ruby>仲介<rt>ちゅうかい</rt></ruby></strong>で秘密交渉が続けられ、1993年にはアメリカ大統領<strong class=\"source-bold\">クリントン</strong>が立ち会って保証人となり、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ<ruby>暫定<rt>ざんてい</rt></ruby>自治協定</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オスロ合意</strong></span>】</strong>が結ばれたよ。</p>\n<p>これは、PLOの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アラファト</strong></span>議長とイスラエルの<strong class=\"source-bold\">ラビン</strong>首相の間で、まず<strong class=\"source-bold\">イスラエルがPLOをパレスチナ人の正式な代表と認めて相互承認</strong>し、さらに<strong class=\"source-bold\">イスラエルの占領地におけるパレスチナ人の暫定自治</strong>を認めた。そして、<strong class=\"source-bold\">ガザ地区とヨルダン川西岸地区に暫定自治政府</strong>をつくることになり、1996年には<strong class=\"source-bold\">アラファトが長官</strong>になった。これは、パレスチナ問題の解決に向けた大きな一歩だよ。そしてこの間に、<strong class=\"source-bold\">イスラエル＝ヨルダン平和条約</strong>も結ばれたんだ。</p>\n<p>ただ、和平を進めたことがイスラエル国内での反発を招き、1995年、<strong class=\"source-bold\">ラビン首相が極右のユダヤ人学生に暗殺</strong>されて、イスラエルはパレスチナとの対決姿勢に戻った。ちょっと前進しても、すぐに逆戻り。中東の混乱はまだまだ続くよ。</p>\n<h3><span data-source-background=\"pink\" data-source-border=\"pink\" data-source-border-width=\"thick\" style=\"background-color:#fce5e5;border:3px solid #f0a0a0;border-radius:0.4em;padding:0 0.2em\"><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">合</span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">否</span><strong class=\"source-bold\">の分かれ目</strong> <span data-source-background=\"white\" data-source-border=\"brown\" data-source-border-style=\"dotted\" style=\"border:1px dotted #a43725;background-color:#fff;padding:0 0.2em\"><strong class=\"source-bold\">中東和平に関係する人物</strong></span></span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプト＝イスラエル平和条約</strong></span>［1979.3］……米大統領<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カーター</strong></span>の仲介</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>エジプト大統領<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サダト</strong></span>、イスラエル首相<strong class=\"source-bold\">ベギン</strong>による</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ暫定自治協定</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オスロ合意</strong></span>】</strong>［1993.9］……<strong class=\"source-bold\">ノルウェー</strong>の仲介</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>アメリカ大統領<strong class=\"source-bold\">クリントン</strong>が立ち会い、中東和平の保証人となる</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>PLOの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アラファト</strong></span>議長とイスラエルの<strong class=\"source-bold\">ラビン</strong>首相による</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <span data-source-background=\"white\" data-source-border=\"red\" data-source-border-pattern=\"diagonal-lines\" style=\"border:1px solid #e52715;background:repeating-linear-gradient(135deg,#fff 0 4px,#fbe1e1 4px 5px);padding:0 0.2em\"><strong class=\"source-bold\">戦後の西アジア（イラン・イラク）</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ イランはアメリカに追従、イラクはイギリス支配から脱却</strong></span></h4>\n<p>話は変わって、イランとイラクだよ。第二次世界大戦期から、<strong class=\"source-bold\">北からのソ連の進出</strong>に苦しんだイランは、国王<strong class=\"source-bold\">パフレヴィー2世</strong>が<strong class=\"source-bold\">アメリカやイギリスの支援</strong>を受けて権力を維持していたんだ。イギリスが守りたいのは<strong class=\"source-bold\">石油利権</strong>だよ。当時、イランの石油はイギリスがつくった<strong class=\"source-bold\">アングロ＝イラニアン石油会社</strong>（1909年に設立した時は、アングロ＝ペルシアン石油会社）が独占していたからね。ただ、イラン人の民族主義者たちは「なんでイギリスに石油を取られるんだよ」って怒っていた。</p>",
  "465": "<h2>465</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後の西アジア（イラン・イラク）</u></p></blockquote>\n<p>そして、「イランで採れた石油はイランのものだ〜」と考えた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モサッデグ</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モサデグ</strong></span>】</strong>首相が、1951年アングロ＝イラニアン石油会社を<ruby>接収<rt>せっしゅう</rt></ruby>して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イランの石油を国有化</strong></span>した。これは、のちに拡大する<strong class=\"source-bold\">資源ナショナリズム</strong>の<ruby>先駆<rt>せんく</rt></ruby>だね。</p>\n<p>これに対し、世界の石油<ruby>市場<rt>しじょう</rt></ruby>を支配する<strong class=\"source-bold\">欧米系の石油メジャー（国際石油資本）がイランの石油をボイコット</strong>すると、イランは<strong class=\"source-bold\">石油生産の激減</strong>で財政が悪化した。そして米英は、<strong class=\"source-bold\">国王派にクーデタを起こさせて、モサッデグを打倒</strong>した。ただ、以前よりはイランにも石油の収入が入るようになった。そして、1955年には<strong class=\"source-bold\">バグダード条約機構にも加盟</strong>し、さらに1963年からは、<strong class=\"source-bold\">開発<ruby>独裁<rt>どくさい</rt></ruby>体制のもと</strong>でアメリカの<ruby>援助<rt>えんじょ</rt></ruby>と石油収入による近代化「<strong class=\"source-bold\"><ruby>白色<rt>はくしょく</rt></ruby>革命</strong>」が進み、イランは西アジアでもっともアメリカ寄りの国になったんだ。そしてベトナム戦争が始まると、中東での影響力が弱まることを恐れたアメリカが、<strong class=\"source-bold\">イランへの武器援助を通じて反イスラエルのアラブ諸国を抑えた</strong>んだ。</p>\n<p>一方、イラクでは、フセイン（フセイン・マクマホン協定のフセイン）のひ<ruby>孫<rt>まご</rt></ruby>にあたる<strong class=\"source-bold\">ファイサル（2世）</strong>がイギリスを後ろ<ruby>盾<rt>だて</rt></ruby>に権力を維持していた。これに対し、民族主義の軍人<strong class=\"source-bold\">カセム</strong>が、<strong class=\"source-bold\">エジプト革命の影響</strong>を受けて自由将校団を結成すると、1958年に<strong class=\"source-bold\">イラク革命</strong>を起こして<strong class=\"source-bold\">国王ファイサル2世を打倒</strong>、イギリス支配から脱却すると、翌年には<strong class=\"source-bold\">バグダード条約機構【中東条約機構】から脱退</strong>したんだ。</p>\n<p>しかし、イギリスの支配下で拡大した<ruby>貧富<rt>ひんぷ</rt></ruby>の格差を解消できなかったから、地主の打倒と社会主義的な平等、さらに<strong class=\"source-bold\">パン＝アラブ主義</strong>（アラブ世界の統一）を主張する<strong class=\"source-bold\">バース党【アラブ<ruby>復興<rt>ふっこう</rt></ruby>社会党】</strong>が勢力を拡大、軍内部のエリートたちと結びついて、1968年にクーデタで政権に<ruby>就<rt>つ</rt></ruby>いた。そして、バース党内の影の実力者だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サダム＝フセイン</strong></span>が反対派を次々と倒して独裁権を握り、1979年には大統領になったんだ。</p>\n<blockquote><p>イラクのサダム＝フセインも、このあと2003年のイラク戦争まで、ずっと独裁だよ！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 「反米」のイラン革命が起こると、アメリカがイラクを支援！</strong></span></h4>\n<p>アメリカの援助で経済が発展したイランでは貧富の格差が拡大して、<strong class=\"source-bold\">アメリカと国王に対する不満</strong>が高まった。しかも、1973年の<strong class=\"source-bold\">第1次石油危機で石油収入は激増</strong>したけど、貧富の格差はますます広がり、国内の矛盾が大きくなっていたんだ。こうした不満は、「信者の絶対平等」を唱える<strong class=\"source-bold\">イスラーム教への<ruby>回帰<rt>かいき</rt></ruby></strong>を引き起こし、政治も文化も全部イスラーム中心にして、「『コーラン』に基づく国づくりをしよう！」という<strong class=\"source-bold\">イスラーム復興運動【イスラーム原理主義】</strong>が勢力を拡大した。そして、<strong class=\"source-bold\">シーア派の指導者</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ホメイニ</strong></span>が<ruby>亡命<rt>ぼうめい</rt></ruby>先のパリから「アメリカに追従する国王を打倒せよ」と訴えると全国に反国王運動が拡大、1979年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラン革命</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラン＝イスラーム革命</strong></span>】</strong>が始まった。そして、<strong class=\"source-bold\">国王パフレヴィー2世が亡命</strong>すると、シ</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "466": "<h2>466</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第25回</strong></span> 戦後の西アジア・アフリカ</p></blockquote>\n<p>ーア派イスラーム教に基づく政治を強行し（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラン＝イスラーム共和国</strong></span>）、<strong class=\"source-bold\">反米・反ソ路線</strong>を明確にした。さらに、ホメイニ派は<strong class=\"source-bold\">テヘランの米大使館を<ruby>占拠<rt>せんきょ</rt></ruby></strong>して、「<ruby>亡命<rt>ぼうめい</rt></ruby>した国王の<ruby>身柄<rt>みがら</rt></ruby>と資産を引渡せ〜」と要求したけど、アメリカは拒否！ 両国の関係は最悪になった。こうして西アジアでもっとも親米だったイランは、<strong class=\"source-bold\">もっとも反米色の強い国になった</strong>んだ。しかも、イランの隣国<strong class=\"source-bold\">アフガニスタンにソ連軍が<ruby>侵攻<rt>しんこう</rt></ruby></strong>したため、イランの周辺では一気にアメリカの影響力が弱まった。さらに、イラン革命の影響で<strong class=\"source-bold\"><ruby>OPEC<rt>オペック</rt></ruby> が石油価格を引き上げた</strong>ため、原油価格は約2倍に高騰し、<strong class=\"source-bold\">第2次石油危機</strong>が起こったんだ。</p>\n<h4><strong class=\"source-bold\">〈1980年代以降の中東情勢〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>地図内の文字</td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">トルコ</strong></span></td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">ソ連</strong></span></td></tr><tr><td><strong class=\"source-bold\">イスラエル</strong></td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">シリア</strong></span></td></tr><tr><td><strong class=\"source-bold\">ヨルダン</strong></td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">エジプト</strong></span></td></tr><tr><td><strong class=\"source-bold\">イラク</strong></td></tr><tr><td><strong class=\"source-bold\">イラン</strong></td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">アフガニスタン</strong></span></td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">サウジアラビア</strong></span></td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">パキスタン</strong></span></td></tr><tr><td><strong class=\"source-bold\">インド</strong></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>地図内の囲み・矢印・凡例</td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">アフガニスタン侵攻［1979］</span> <span data-source-color=\"red\" data-source-marker=\"arrow\" data-source-outline-color=\"black\" data-source-line-width=\"thick\" style=\"color:#e52715;text-shadow:1px 0 #001000,-1px 0 #001000,0 1px #001000,0 -1px #001000\"><strong class=\"source-red-bold\">↓</strong></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">イラン＝イラク戦争［1980〜88］</span> <span data-source-color=\"red\" data-source-marker=\"arrow\" data-source-outline-color=\"black\" data-source-line-width=\"thick\" style=\"color:#e52715;text-shadow:1px 0 #001000,-1px 0 #001000,0 1px #001000,0 -1px #001000\"><strong class=\"source-red-bold\">↔</strong></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">イラン革命［1979］<br>反米・反ソ</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">クウェート侵攻［1990］<br>湾岸戦争</span> <span data-source-color=\"red\" data-source-marker=\"arrow\" data-source-outline-color=\"black\" data-source-line-width=\"thick\" style=\"color:#e52715;text-shadow:1px 0 #001000,-1px 0 #001000,0 1px #001000,0 -1px #001000\"><strong class=\"source-red-bold\">↘</strong></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">反中国・反パキスタン</span></td></tr><tr><td><span data-source-color=\"gray-green\" data-source-marker=\"area\" style=\"color:#8d977f\">■</span> 親米政権の国</td></tr><tr><td><span data-source-color=\"red\" data-source-marker=\"area\" style=\"color:#e52715\">■</span> 親ソ政権の国</td></tr></tbody></table></div>\n<blockquote><p>イランへの<ruby>恨<rt>うら</rt></ruby>みが強すぎて、アメリカは反イスラエルのイラクを支援……。ソ連はアフガニスタン侵攻で手いっぱいだ……</p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>関係図内の国名</td></tr><tr><td><span data-source-border=\"green\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #89967b;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">イスラエル</strong></span></td></tr><tr><td><span data-source-border=\"brown\" data-source-border-width=\"thick\" style=\"border:3px solid #a43725;padding:0 0.2em\"><strong class=\"source-bold\">イラク</strong></span></td></tr><tr><td><span data-source-border=\"red\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #e52715;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">イラン</strong></span></td></tr><tr><td><span data-source-border=\"green\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #89967b;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">アメリカ</strong></span></td></tr><tr><td><span data-source-border=\"pink\" data-source-border-width=\"thick\" style=\"border:3px solid #f0a0a0;padding:0 0.2em\"><strong class=\"source-bold\">ソ連</strong></span></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>関係図内の文字・線・矢印</td></tr><tr><td>イスラエル <span data-source-color=\"red\" data-source-line-style=\"dotted\" style=\"color:#e52715;border-bottom:1px dotted #e52715\">↔</span> イラク：対立</td></tr><tr><td>イラク <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">↔</strong></span> イラン：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラン＝イラク戦争</strong></span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">反米・反ソ</strong></span></td></tr><tr><td>アメリカ <span data-source-color=\"green\" style=\"color:#315837\">━</span> イスラエル：支援</td></tr><tr><td>アメリカ ━ イラク：支援</td></tr><tr><td>ソ連 ━ イラク：支援</td></tr><tr><td>アメリカ <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">↔</strong></span> イラン：敵対</td></tr><tr><td>アメリカ <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">↔</strong></span> ソ連：冷戦</td></tr></tbody></table></div>",
  "467": "<h2>467</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後の西アジア（イラン・イラク）</u></p></blockquote>\n<p>一方で、国内でシーア派を抑圧していたイラクの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サダム＝フセイン</strong></span>は、「<strong class=\"source-bold\">イラン革命が国内のシーア派に波及するのを阻止する</strong>」と言ってイランに奇襲攻撃をかけ、1980年<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラン＝イラク戦争</strong></span>が始まったんだ。まあ、本音ではイランからの領土回復やアラブ地域での<ruby>覇権<rt>はけん</rt></ruby>を握るのが目的だけどね。<strong class=\"source-bold\">アメリカ</strong>は反米のイランを警戒して<strong class=\"source-bold\">イラクに武器を支援</strong>、さらに<ruby>冷戦<rt>れいせん</rt></ruby>を背景にずっとイラクを支援していた<strong class=\"source-bold\">ソ連も武器を供給</strong>したため、戦争は長期化した。しかもアメリカは、王政時代のイランにさんざん武器を<ruby>援助<rt>えんじょ</rt></ruby>して「中東一の軍事大国」にしていたから、イラクにまで武器を支援したら、戦争は決着しなくなるよ。さらに、両国がペルシア湾を通る船を無差別攻撃したために<strong class=\"source-bold\">石油輸送が激減</strong>し、原油価格はどんどん上がったんだ。こうして長期化した戦争が全然終わらないから、日本では「イライラ戦争」なんて呼んでいたよ。ただ、1988年にアメリカのイージス艦の攻撃を受けた<strong class=\"source-bold\">イランが国連<ruby>安保理<rt>あんぽり</rt></ruby>の停戦決議に合意</strong>し、事実上<strong class=\"source-bold\">イランの敗戦</strong>で終わったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 冷戦終結後も不安定な中東情勢。イラクをめぐるアメリカの2つの戦争</strong></span></h4>\n<p>イラン＝イラク戦争が終わると、<strong class=\"source-bold\">イラクのサダム＝フセイン大統領</strong>は、今度は「第一次世界大戦後に英仏が勝手につくった国<strong class=\"source-bold\">クウェート</strong>は、そもそもイラクの領土である」と主張し、さらに「クウェートが石油を増産して、世界の石油価格を不当に下げている」だの、「クウェートが国境付近の石油を盗んでる」だの次々と言いがかりをつけ、ついに1990年8月、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラク軍がクウェートに侵攻</strong></span>した。</p>\n<p>これに対し、国連安保理は、最初は経済<ruby>制裁<rt>せいさい</rt></ruby>を、さらに対<strong class=\"source-bold\">イラク武力行使容認決議</strong>を<ruby>採択<rt>さいたく</rt></ruby>したんだ。そして、<strong class=\"source-bold\">安保理決議に基づいて</strong>、アメリカの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブッシュ（父）</strong></span>大統領を中心に英仏など28カ国が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">多国籍軍</strong></span>を編成、イラクを攻撃した。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>湾岸<rt>わんがん</rt></ruby>戦争</strong></span>だよ。この時アメリカ軍はハイテク兵器を駆使した「<ruby>砂漠<rt>さばく</rt></ruby>の嵐」作戦で、イラク軍を圧倒したんだ。今ではスマートフォンにも付いているGPS や、電波を発しながら敵を追跡して攻撃するミサイルなどで、ピンポイント爆撃をやったんだよ。そして、海外派兵ができない<strong class=\"source-bold\">日本やドイツは膨大な資金援助を要請された</strong>んだ。</p>\n<p>この時フセインは、「イスラエルがパレスチナの<ruby>占領<rt>せんりょう</rt></ruby>地から撤退すれば、イラクもクウェートから撤退する」と、戦争をパレスチナ問題にすり替えようとしたんだけど、アラブ諸国やイスラーム世界の対応は分裂、<strong class=\"source-bold\">エジプト、サウジアラビア、シリア、トルコは多国籍軍に参加</strong>したけど、<strong class=\"source-bold\">ヨルダン、イエメン、PLO はイラクを支持</strong>したよ。結局、多国籍軍（ほぼアメリカ軍）の圧倒的な兵力の前に<strong class=\"source-bold\">イラクが停戦決議を受け入れた</strong>。ただ、<strong class=\"source-bold\">サダム＝フセイン政権はそのまま残った</strong>から、このあともう一度アメリカがイラクを攻撃することになるよ。</p>\n<p>2001年、アメリカで起きた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">同時多発テロ事件</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">9.11事件</strong></span>】</strong>のあと、「<strong class=\"source-bold\">テロとの戦い</strong>」を強硬に主張していたアメリカの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブッシュ（子）</strong></span>大統領は、「イラクは大量破壊兵器を保有している。<strong class=\"source-bold\">イラン・イラク・北朝鮮は</strong> “<strong class=\"source-bold\">悪の<ruby>枢軸<rt>すうじく</rt></ruby></strong>”だ」と主張して、イラクへの攻撃を計画した。この時ブッシュは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフガニスタンも攻撃</strong></span>していたから、アフガン戦争とイラク攻撃を連動させて、中東最大の反米国家イランに圧力を</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "468": "<h2>468</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第25回</strong></span> 戦後の西アジア・アフリカ</p></blockquote>\n<p>かけようとしたんだね。</p>\n<p>そして2003年、<strong class=\"source-bold\">国連決議もないまま</strong>アメリカの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブッシュ（子）</strong></span>大統領は<strong class=\"source-bold\">イギリス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブレア</strong></span>首相とともに、イラクへの攻撃を開始した。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米英軍のイラク攻撃</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イラク戦争</strong></span>）で<strong class=\"source-bold\">サダム＝フセイン政権は崩壊</strong>、フセインも<ruby>身柄<rt>みがら</rt></ruby>を<ruby>拘束<rt>こうそく</rt></ruby>され、翌年には<ruby>暫定<rt>ざんてい</rt></ruby>政府ができた。さらに、2006年にはサダム＝フセインはアメリカのもとでおこなわれたイラク高等法廷で死刑判決を受け、処刑されたんだ。また、イラクの<ruby>復興<rt>ふっこう</rt></ruby>支援のため、日本の<strong class=\"source-bold\"><ruby>小泉純一郎<rt>こいずみじゅんいちろう</rt></ruby>首相</strong>が<strong class=\"source-bold\">イラク復興特別措置法</strong>に基づいて<strong class=\"source-bold\">自衛隊を派遣</strong>した。これは、<strong class=\"source-bold\">日本が初めて重火器を携行しておこなった海外派遣</strong>だ！。</p>\n<p>フセイン政権は倒れたけど、結局<strong class=\"source-bold\">イラクに大量破壊兵器などなかった</strong>よね。ブッシュが「勝利宣言」を出したあとも約16万人もの米軍がイラクに残ったし、イラク内部では<strong class=\"source-bold\">多数派のシーア派とスンナ派の対立</strong>や<strong class=\"source-bold\">クルド人問題</strong>で混乱が続いたんだ。その後、アメリカの<strong class=\"source-bold\">オバマ</strong>大統領はイラクからの撤退を発表し、2011年12月に<strong class=\"source-bold\">イラク戦争終結を宣言</strong>したよ。</p>\n<h4><span data-source-border=\"pink\" data-source-border-shape=\"scalloped\" data-source-border-style=\"double\" style=\"border:3px double #f0a0a0;border-radius:1em;padding:0 0.3em\"><strong class=\"source-bold\">＋<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">α</strong></span> <u data-source-underline-color=\"black\" style=\"text-decoration-color:#222222\">ちょっと寄り耳</u> ↗</strong></span></h4>\n<blockquote><p>ここで、現代まで問題として残っているクルド人の話をしておこう！</p>\n<p>クルド人は、イラン系の言語を使い、トルコ・イラン・イラクにまたがる地域に住んでいる民族だよ。現在、約1500〜2000万人のクルド人がいるといわれ、大部分はスンナ派イスラーム教徒だ。彼らは、オスマン帝国が解体する際に独立国家をつくる運動をおこない、1920年のセーヴル条約では自治領構想が認められたものの、1923年のローザンヌ条約ではこの構想が無視された。1925年にはトルコに対する反乱を起こすものの<ruby>鎮圧<rt>ちんあつ</rt></ruby>され、第二次世界大戦後には、ソ連の支援で一時北西イランにクルディスタン共和国を建設するものの、やはりイラン政府によって<ruby>潰<rt>つぶ</rt></ruby>され、現在まで彼らは国家を持たないままだ。また、イラク国内のクルド人はサダム＝フセインによって<ruby>弾圧<rt>だんあつ</rt></ruby>され、毒ガスで大量<ruby>虐<rt>ぎゃく</rt></ruby><ruby>殺<rt>さつ</rt></ruby>され、反乱は徹底的に<ruby>潰<rt>つぶ</rt></ruby>されたんだ。</p>\n<p>その後、イラク戦争でサダム＝フセイン政権が崩壊し、2005年には、クルド人のタラバーニーがイラク大統領になったんだ！ <ruby>列強<rt>れっきょう</rt></ruby>の<ruby>覇権<rt>はけん</rt></ruby>争いの陰で、辛い目にあい続けたクルド人が、少しでも幸せに暮らせる日がくるといいね。</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <span data-source-background=\"white\" data-source-border=\"red\" data-source-border-pattern=\"diagonal-lines\" style=\"border:1px solid #e52715;background:repeating-linear-gradient(135deg,#fff 0 4px,#fbe1e1 4px 5px);padding:0 0.2em\"><strong class=\"source-bold\">戦後のアフリカ</strong></span></h3>\n<h4><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈アフリカ諸国の独立〉</strong></span></h4>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 北アフリカ諸国が独立する一方、アルジェリアでは壮絶な戦争が！</strong></span></h4>\n<p>それじゃあ、アフリカ諸国の独立を見ていこう。アフリカ諸国のうち、まず<strong class=\"source-bold\">独立が進んだのは北アフリカ</strong>だよ。もっとも、地中海沿岸の国は黒人国家じゃないからね。まず、1951年に旧イタリア領で連合国が占領していた<strong class=\"source-bold\">リビア</strong>が独立する</p>",
  "469": "<h2>469</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後のアフリカ</u></p></blockquote>\n<p>と、続いて1956年には、フランス領だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モロッコ</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チュニジア</strong></span>も独立したよ。この2国は、<strong class=\"source-bold\">ナセルの「非同盟主義」にも影響を受けている</strong>ね。ただ、アルジェリアだけは簡単には独立できなかった。</p>\n<p>1954年、ジュネーヴ休戦協定でインドシナの独立を認めたフランスは、なんとしても<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルジェリア</strong></span>だけは植民地支配を維持しようと、支配を強化した。これに対し、アルジェリアでは<strong class=\"source-bold\">民族解放戦線【FLN】</strong>が結成されて独立闘争を開始、壮絶な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルジェリア戦争</strong></span>が始まったよ。FLN は全国的なゲリラ戦を展開してフランス軍を苦しめ、<strong class=\"source-bold\">戦争の泥沼化でフランスの財政は傾き始めた</strong>。そしてフランスでは、特に軍の内部から「もっと強力な指導者を！」と期待されて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ド＝ゴール</strong></span>が政界に復帰、<strong class=\"source-bold\">第五共和政</strong>を成立させて大統領になったんだ。ただ、アルジェリア戦争の戦況はほとんど変わらず、ついに1962年、ド＝ゴールは入植者<strong class=\"source-bold\">【コロン】</strong>や現地軍の反対を押し切って<strong class=\"source-bold\">エヴィアン協定</strong>を結び、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルジェリアの独立を承認</strong></span>したよ。</p>\n<p>アルジェリアでは<strong class=\"source-bold\">ベン＝ベラ</strong>が初代大統領となり、独自のアラブ社会主義を目指したんだけど、1965年には民族解放軍の司令官だった<strong class=\"source-bold\">ブーメジェンのクーデタで軍部<ruby>独裁<rt>どくさい</rt></ruby>政権</strong>になってしまったんだ［〜1989］。</p>\n<blockquote><p>ド＝ゴールの政策で、フランス領の独立が一気に進むよ！</p></blockquote>\n<h4><strong class=\"source-bold\">〈戦後のアフリカ〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>地図内の文字</td></tr><tr><td><strong class=\"source-bold\">モロッコ</strong>［1956］</td></tr><tr><td><strong class=\"source-bold\">チュニジア</strong>［1956］</td></tr><tr><td><strong class=\"source-bold\">アルジェリア</strong></td></tr><tr><td><strong class=\"source-bold\">リビア</strong>［1951］</td></tr><tr><td><strong class=\"source-bold\">エジプト</strong></td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">スーダン</strong></span></td></tr><tr><td><strong class=\"source-bold\">ギニア</strong></td></tr><tr><td><strong class=\"source-bold\">ナイジェリア</strong></td></tr><tr><td><strong class=\"source-bold\">ガーナ</strong></td></tr><tr><td><strong class=\"source-bold\">コンゴ</strong><br>（旧ベルギー領）</td></tr><tr><td>カタンガ州</td></tr><tr><td><strong class=\"source-bold\">ルワンダ</strong></td></tr><tr><td><strong class=\"source-bold\">エチオピア</strong></td></tr><tr><td><span data-source-color=\"black\" data-source-outline-color=\"white\" style=\"color:#001000;text-shadow:1px 0 #fff,-1px 0 #fff,0 1px #fff,0 -1px #fff\"><strong class=\"source-bold\">ソマリア</strong></span></td></tr><tr><td><strong class=\"source-bold\">アンゴラ</strong></td></tr><tr><td><strong class=\"source-bold\">モザンビーク</strong></td></tr><tr><td><strong class=\"source-bold\">南アフリカ共和国</strong></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>地図内の囲み</td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">アルジェリア戦争［1954〜］<br>→独立達成［1962］</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">エチオピア革命［1974］</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">南スーダン独立［2011］</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ナイジェリア内戦（ビアフラ戦争）［1967〜70］</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ソマリア内戦［1980年代〜］</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ルワンダ内戦［1990〜94］</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">コンゴ動乱［1960〜65］</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ナミビア独立［1990］</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">アパルトヘイト法的撤廃［1991］</span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ローデシア<br>→ジンバブエ［1980］</span></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>地図内の領域の表示</td></tr><tr><td><span data-source-color=\"red\" data-source-marker=\"hatch\" data-source-pattern=\"diagonal-lines\" style=\"color:#e52715\">▨</span> ナイジェリア</td></tr><tr><td><span data-source-color=\"gray-green\" data-source-marker=\"hatch\" data-source-pattern=\"vertical-lines\" style=\"color:#9b9f8e\">▥</span> コンゴ（旧ベルギー領）</td></tr><tr><td><span data-source-color=\"green\" data-source-marker=\"area\" style=\"color:#64775b\">■</span> スーダン</td></tr><tr><td><span data-source-color=\"brown\" data-source-marker=\"area\" style=\"color:#bd8a80\">■</span> ソマリア</td></tr><tr><td><span data-source-color=\"red\" data-source-marker=\"area\" style=\"color:#e52715\">■</span> ルワンダ</td></tr></tbody></table></div>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "470": "<h2>470</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第25回</strong></span> 戦後の西アジア・アフリカ</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ いよいよブラック＝アフリカ諸国が独立し、パン＝アフリカニズムを推進！</strong></span></h4>\n<p>アフリカでは、すでに20世紀初めから、南アフリカにおける<strong class=\"source-bold\">アフリカ民族会議【ANC】</strong>の人種差別撤廃運動など、民族の自治や独立を目指す運動が広がっていた。また<strong class=\"source-bold\">南北アメリカの黒人知識人を中心とする解放運動</strong>も生まれ、1900年には<strong class=\"source-bold\">パン＝アフリカ会議</strong>が開かれて、植民地主義や人種差別への反対が唱えられた。そして、1940年代にはこれらの運動が合体し、<strong class=\"source-bold\">ガーナ</strong>（ゴールドコースト）の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エンクルマ</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ンクルマ</strong></span>】</strong>などを指導者に、<strong class=\"source-bold\">アフリカ系民族（黒人）の団結</strong>によって独立運動を活発化させる「<strong class=\"source-bold\">パン＝アフリカニズム</strong>」が高揚したから、1950年代後半に入ると<strong class=\"source-bold\">サハラ砂漠より南の黒人世界（ブラック＝アフリカ）</strong>の国々も独立し始めるよ。</p>\n<p>まず1957年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ガーナ</strong></span>が<strong class=\"source-bold\">イギリス連邦内の自治領として独立</strong>したよ。これが<strong class=\"source-bold\">ブラック＝アフリカ最初の自力独立国</strong>だ。そして、1958年にはガーナの首都アクラで<strong class=\"source-bold\">全アフリカ人民会議</strong>を開いてアフリカの即時独立を要求するとともに、<strong class=\"source-bold\">アフリカ統一運動</strong>（つまりパン＝アフリカニズムだ）を進めたんだ。これは、「独立直後のアフリカ諸国は弱いから、アフリカを統一することで、欧米の旧<ruby>宗主国<rt>そうしゅこく</rt></ruby>に対抗しよう」ってことだ。さらに、1958年に<strong class=\"source-bold\">フランスから独立</strong>した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ギニア</strong></span>の初代大統領<strong class=\"source-bold\">セク＝トゥーレ</strong>は、エンクルマのパン＝アフリカニズムに共鳴して、ともにアフリカ統一運動の中心になったよ。</p>\n<p>そして1960年、<strong class=\"source-bold\">フランスのド＝ゴール</strong>が「植民地の独立を認めて第三世界の支持を得る」という政策をとったことから、<strong class=\"source-bold\">旧フランス領を中心に17カ国が一気に独立</strong>した。この「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフリカの年</strong></span>」に独立した国には、仏領だったセネガル、カメルーン、マダガスカル、マリなど、英領だった<strong class=\"source-bold\">ナイジェリア</strong>、トーゴ、ソマリア（英・伊領）など、さらに<strong class=\"source-bold\">ベルギー領コンゴ</strong>があるよ。</p>\n<p>そして、1963年には<strong class=\"source-bold\">エチオピアのアディスアベバ</strong>で、アフリカの独立国30カ国による<strong class=\"source-bold\">アフリカ諸国首脳会議</strong>が開かれ、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフリカ統一機構</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">OAU</strong></span>】</strong>が結成されると、パン＝アフリカニズムに基づいて「アフリカは1つ」のスローガンを掲げ、植民地主義の一掃や国連<ruby>憲章<rt>けんしょう</rt></ruby>の尊重などを唱えたんだ。ただし、アパルトヘイトをやっていた<strong class=\"source-bold\">南アフリカ、ローデシアは加盟していなかった</strong>からね。</p>\n<p>ただ、1966年にはガーナの軍部クーデタで<strong class=\"source-bold\">エンクルマが失脚</strong>しちゃった！。エンクルマはギニアに<ruby>亡命<rt>ぼうめい</rt></ruby>し、以後、<strong class=\"source-bold\">アフリカ統一運動の中心はギニアのセク＝トゥーレ</strong>になったよ。そして、<ruby>冷戦<rt>れいせん</rt></ruby>終結後の1991年にはアフリカ統一機構が経済統合を目指して<strong class=\"source-bold\">アフリカ経済共同体</strong>を創設し、2002年にはEU をモデルにした地域統合機構として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフリカ連合</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">AU</strong></span>】</strong>になった。でも、アフリカ全体をリードする国はどこなのか？ あるいは、各地で続く内戦への対応や、EU でさえ難しい地域統合の問題をどのように進めるのか、課題も多いよね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 独立を達成したあとも、国内の部族対立に苦しむアフリカ諸国</strong></span></h4>\n<p>さて、独立を達成したアフリカ諸国だけど、独立すればすべてがうまくいくってわけじゃない！ 独立後に国内の分裂や内戦に苦しんだ国は多いよ。</p>",
  "471": "<h2>471</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後のアフリカ</u></p></blockquote>\n<p>1960年にイギリスから独立した<strong class=\"source-bold\">ナイジェリア</strong>では、<strong class=\"source-bold\">東部に住むキリスト教徒のイボ族</strong>と、<strong class=\"source-bold\">北部に住むイスラーム教徒のハウサ族</strong>の対立が激しくなったんだ。もともと<strong class=\"source-bold\">イボ族</strong>は、イギリスの<ruby>奴隷<rt>どれい</rt></ruby>貿易の最大の<strong class=\"source-bold\">犠牲者</strong>だよ！ 1950年代にイボ族の住む東部州で<ruby>油田<rt>ゆでん</rt></ruby>が発見され、独立後に工業化が進んだ東部のイボ族地域が<strong class=\"source-bold\">ビアフラ共和国</strong>として独立を宣言すると、北部のハウサ族（政府軍）がビアフラを攻撃し、内戦になった（<strong class=\"source-bold\">ナイジェリア内戦【ビアフラ戦争】</strong>）。石油が<ruby>絡<rt>から</rt></ruby>んでいるから、利権をめぐる<ruby>介入<rt>かいにゅう</rt></ruby>が起きるよ。結局、<strong class=\"source-bold\">政府軍をイギリスとソ連が支援</strong>して、<strong class=\"source-bold\">ビアフラ軍は壊滅</strong>したんだ。</p>\n<blockquote><p>ナイジェリア内戦は、石油利権から内戦が激化したんだ…… やっぱり、資源狙いだよな</p></blockquote>\n<p>同じように資源をめぐる対立から戦争になったのが、<strong class=\"source-bold\">ベルギー領コンゴ</strong>だ。1960年に<strong class=\"source-bold\">コンゴ共和国</strong>として独立すると、地方分権派の<strong class=\"source-bold\">カサヴブ</strong>が初代大統領、中央集権派の<strong class=\"source-bold\">ルムンバ</strong>が初代首相となった。しかし、首相の<strong class=\"source-bold\">ルムンバが社会主義</strong>に向かおうとしたから、<strong class=\"source-bold\">独立直後にベルギー軍が介入</strong>して、<strong class=\"source-bold\">銅・ウラン・コバルトなどの鉱山資源</strong>が採れる<strong class=\"source-bold\">カタンガ州</strong>の分離独立を宣言させた。結局、資源の確保が狙いだよ。こうして<strong class=\"source-bold\">コンゴは内戦となり</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コンゴ動乱</strong></span>）、国連<ruby>安保理<rt>あんぽり</rt></ruby>は、結成以来初めて<strong class=\"source-bold\">平和維持軍の派遣を決めた</strong>よ。そしてアメリカは「社会主義化を阻止する」と、軍部のモブツを支援して<strong class=\"source-bold\">ルムンバを殺害させた</strong>。</p>\n<p>1963年には国連平和維持軍の介入でいったん動乱は終わったんだけど（<strong class=\"source-bold\">第1次動乱</strong>）、平和維持軍の撤退とともに内戦が再開したため（<strong class=\"source-bold\">第2次動乱</strong>）、今度は<strong class=\"source-bold\">アメリカ軍とベルギー軍が介入</strong>して、反政府軍を<ruby>鎮圧<rt>ちんあつ</rt></ruby>した。これも資源狙いだよね。最終的には<strong class=\"source-bold\">モブツを大統領とする親米軍事政権</strong>となり、そして国名も<strong class=\"source-bold\">ザイール共和国</strong>に変わった。ただ1996年に<strong class=\"source-bold\">反モブツ勢力の武装<ruby>蜂起<rt>ほうき</rt></ruby>で政権が交代</strong>し、現在は国名が<strong class=\"source-bold\">コンゴ民主共和国</strong>になってるよ。</p>\n<h4><strong class=\"source-bold\">〈コンゴ動乱〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>図内の国名・人物名・地名</td></tr><tr><td><span data-source-border=\"black\" data-source-border-style=\"dashed\" style=\"border:1px dashed #001000;padding:0 0.2em\"><strong class=\"source-bold\">コンゴ</strong></span></td></tr><tr><td><span data-source-border=\"pink\" data-source-border-width=\"thick\" style=\"border:3px solid #f0a0a0;padding:0 0.2em\"><strong class=\"source-bold\">ソ連</strong></span></td></tr><tr><td><span data-source-border=\"red\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #e52715;border-radius:0.2em;padding:0 0.2em\"><span data-source-cancellation=\"cross\" data-source-cancellation-color=\"black\" style=\"background-image:linear-gradient(45deg,transparent 48%,#001000 48% 52%,transparent 52%),linear-gradient(135deg,transparent 48%,#001000 48% 52%,transparent 52%)\"><strong class=\"source-bold\">ルムンバ</strong><br>（首相）</span></span></td></tr><tr><td><span data-source-border=\"green\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #89967b;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">モブツ</strong><br>（軍司令官）</span></td></tr><tr><td><span data-source-border=\"brown\" data-source-border-style=\"dotted\" data-source-border-width=\"thick\" style=\"border:3px dotted #a43725;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">カタンガ州</strong><br>（資源の宝庫）</span></td></tr><tr><td><span data-source-border=\"green\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #89967b;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">アメリカ</strong></span></td></tr><tr><td><span data-source-border=\"green\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #89967b;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">国連</strong></span></td></tr><tr><td><span data-source-border=\"green\" data-source-border-style=\"solid\" data-source-border-width=\"thick\" style=\"border:3px solid #89967b;border-radius:0.2em;padding:0 0.2em\"><strong class=\"source-bold\">ベルギー</strong></span></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>図内の線・矢印・文字</td></tr><tr><td>ソ連 <span data-source-color=\"pink\" style=\"color:#f0a0a0\">━</span> ルムンバ</td></tr><tr><td>ルムンバ <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">↔</strong></span> モブツ</td></tr><tr><td><span data-source-cancellation=\"cross\" data-source-cancellation-color=\"black\" style=\"background-image:linear-gradient(45deg,transparent 48%,#001000 48% 52%,transparent 52%),linear-gradient(135deg,transparent 48%,#001000 48% 52%,transparent 52%)\">×</span> 逮捕・処刑</td></tr><tr><td>アメリカ <span data-source-color=\"green\" style=\"color:#315837\">━</span> モブツ</td></tr><tr><td>国連 <span data-source-color=\"green\" style=\"color:#315837\">━</span> モブツ</td></tr><tr><td>モブツ <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">↙</strong></span> カタンガ州：制圧</td></tr><tr><td>カタンガ州 <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">←</strong></span> ベルギー：侵攻</td></tr></tbody></table></div>\n<p>最近では、<strong class=\"source-bold\">スーダンと南スーダンの問題</strong>もあるね。スーダンは、すでに1956年にはイギリスとエジプトの共同<ruby>統治<rt>とうち</rt></ruby>領から、<strong class=\"source-bold\">スーダン共和国</strong>として独立していたんだけど、<strong class=\"source-bold\">北部のアラブ系イスラーム教徒</strong>と、<strong class=\"source-bold\">南部の黒人系キリスト教徒</strong>がずっと対立して、たびたび武装闘争に発展していた（ダルフール紛争）。それが21世紀になっても続いていたんだけど、ついに2011年、<strong class=\"source-bold\">南スーダン共和国</strong>が<strong class=\"source-bold\">スーダンから分離・独立</strong>して、<strong class=\"source-bold\">国連への加盟</strong>も認められた。ほんと、長い戦争の歴史がやっと終わった</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "472": "<h2>472</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第25回</strong></span> 戦後の西アジア・アフリカ</p></blockquote>\n<p>んだね。</p>\n<p>第一次世界大戦直前の数少ない独立国の1つだった<strong class=\"source-bold\">エチオピア</strong>は、一時<strong class=\"source-bold\">イタリアに<ruby>併合<rt>へいごう</rt></ruby></strong>されていたけど、1941年には<strong class=\"source-bold\">独立を回復</strong>していたよ。ただ、独立国とはいっても国内は皇帝の<strong class=\"source-bold\"><ruby>独裁<rt>どくさい</rt></ruby>体制</strong>で、いまだに<ruby>農奴<rt>のうど</rt></ruby>制のような<ruby>封建<rt>ほうけん</rt></ruby>体制が残っていたから、経済的には全く発展していなかった。そして、1973年の<strong class=\"source-bold\">第1次石油危機</strong>によるインフレーションや、相次ぐ干ばつで経済危機になったエチオピアでは、<strong class=\"source-bold\">軍部クーデタ</strong>で皇帝<strong class=\"source-bold\">ハイレ＝セラシエ</strong>を廃位して、<strong class=\"source-bold\">軍部主導で社会主義政権を樹立</strong>した。これが<strong class=\"source-bold\">エチオピア革命</strong>だよ。ただ、経済危機はさらに深刻となり、国内の<ruby>飢餓<rt>きが</rt></ruby>状態が続き、しかも1993年以降は分離独立したエリトリアとの国境紛争や、内戦で混乱が続いているから、経済状態はますます悪化しているんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 最後の植民地帝国ポルトガルからの独立</strong></span></h4>\n<p>第二次世界大戦前から<strong class=\"source-bold\">サラザールの独裁</strong>が続き、彼の引退後も独裁政権が続いていた<strong class=\"source-bold\">ポルトガルは植民地の独立を認めなかった</strong>から、現地の黒人勢力による独立闘争が起きていた。しかし、<strong class=\"source-bold\">第1次石油危機で経済が落ち込んで本国財政が厳しくなった</strong>こともあって、植民地の独立運動を武力で抑圧することに反対する動きが広がった。そして1974年、<strong class=\"source-bold\">若手将校が起こした革命で独裁政権が倒れ</strong>（<strong class=\"source-bold\">カーネーション革命</strong>）、新政府が植民地の独立を認めたから、1975年には<strong class=\"source-bold\">アンゴラ</strong>と<strong class=\"source-bold\">モザンビーク</strong>が独立したよ。<strong class=\"source-bold\">モザンビークは社会主義政権（モザンビーク人民共和国）になった</strong>から、隣国のローデシアや南アフリカは支援する白人勢力との抗争が続くことになるよ。また<strong class=\"source-bold\">アンゴラ内戦</strong>も起きて、キューバ軍と南アフリカ軍が投入されたんだけど、これは米ソの代理戦争になって長期化したんだ。</p>\n<h4><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈南アフリカのアパルトヘイト〉</strong></span></h4>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ イギリス領の時代に始まったアパルトヘイトが、第二次世界大戦後まで続く！</strong></span></h4>\n<p>南アフリカ戦争【ブール戦争】後に<strong class=\"source-bold\">イギリスの自治領</strong>となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南アフリカ連邦</strong></span>では、イギリスがブール人を<ruby>懐柔<rt>かいじゅう</rt></ruby>するために始めた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アパルトヘイト</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人種<ruby>隔離<rt>かくり</rt></ruby>政策</strong></span>）に対して、1912年人種差別<ruby>撤廃<rt>てっぱい</rt></ruby>を目指して<strong class=\"source-bold\">アフリカ民族会議【ANC】</strong>が結成され、<strong class=\"source-bold\">非暴力主義に基づく黒人解放運動</strong>をおこなっていたよ。</p>\n<p>でも人種差別はなくならず、逆に1949年以降、<strong class=\"source-bold\">白人政権</strong>（アフリカーナと呼ばれるオランダ系白人）によって<strong class=\"source-bold\">アパルトヘイトがさらに強化</strong>された。住民を<strong class=\"source-bold\">白人、黒人、カラード（混血）、アジア人（おもにインド系）</strong>の4つの人種グループに分けて、社会のあらゆる分野で各人種、特に黒人を「別々」の社会に隔離しよう、っていうのがアパルトヘイトの目的だよ。そのために<strong class=\"source-bold\">先住民土地法</strong>などに加え、<strong class=\"source-bold\">人口登録法、集団地域法</strong>などの法律（この3つがアパルトヘイト基幹3法だよ）をつくったんだ。</p>\n<p>こうした政策に反発した黒人はたびたびデモや暴動を起こしたんだけど、1960年の<strong class=\"source-bold\">シャープビル事件</strong>（首都ヨハネスブルク近郊での黒人のデモに警官が発砲）のよ</p>",
  "473": "<h2>473</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後のアフリカ</u></p></blockquote>\n<p>うに、厳しく<ruby>弾圧<rt>だんあつ</rt></ruby>された。そして、<strong class=\"source-bold\">アフリカ諸国が独立を達成した</strong>1960年代には（1960年が「アフリカの年」だ！）、<strong class=\"source-bold\">黒人運動がさらに過激</strong>となったため、黒人を領土的に隔離する「<strong class=\"source-bold\">ホームランド</strong>」政策など、さらにアパルトヘイトは強化されていった。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ イギリス連邦から離脱してアパルトヘイトを強行した南アフリカとローデシア！</strong></span></h4>\n<p>こうした批判に対し、さすがにイギリス連邦の中心であるイギリスも「そろそろ人種差別は見直したほうが……」と言ったら、南アフリカは「お前が始めたんだろ！」と反発。1961年、<strong class=\"source-bold\">アパルトヘイトを維持するためにイギリス連邦から離脱</strong>して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南アフリカ共和国</strong></span>になった。こうした事態に、<strong class=\"source-bold\">国連も制裁</strong>を決めたんだけど、南アフリカは「金とダイヤが出るから、お金はある」とばかりにアパルトヘイトを続け、<strong class=\"source-bold\">アフリカ民族会議【ANC】を非合法</strong>として、<strong class=\"source-bold\">指導者のマンデラを逮捕</strong>するなど弾圧を強めたんだ。同じようにイギリスの支配下にあったローデシアでは、北ローデシアが黒人政権のザンビア共和国として独立したんだけど、南ローデシアでは白人政権がイギリス連邦から一方的に離脱し、国名を<strong class=\"source-bold\">ローデシア</strong>として<strong class=\"source-bold\">アパルトヘイト維持のために独立を宣言</strong>した。もちろんイギリスも国連も承認しなかったんだけどね。</p>\n<p>いくら独立したといっても、南アフリカとローデシアは<strong class=\"source-bold\">アフリカ統一機構【OAU】には加盟できない</strong>。そりゃそうだ。OAU は黒人主導のパン＝アフリカニズムを掲げた国際機関だし、ローデシアは国際的に独立を認められてないからね。</p>\n<p>その後、ローデシアでは<strong class=\"source-bold\">白人政権と黒人組織の間で武装闘争が激化</strong>したんだ（ローデシア<ruby>紛争<rt>ふんそう</rt></ruby>）。白人政権は南アフリカなどの支援を受け、一方の黒人勢力は、あらたにポルトガルから独立した隣国のモザンビークやソ連などの支援を受けたから、近隣の諸国を巻きこむ地域紛争に発展してしまった。ただ、南アフリカよりも国の経済基盤が弱かったローデシアは、黒人政権となったモザンビークに海への交通路を握られたこともあって、白人政権が弱体化し、1979年には<strong class=\"source-bold\">黒人勢力が勝利して、正式に独立を達成</strong>し、<strong class=\"source-bold\">OAU にも加盟</strong>できた。もちろん、アパルトヘイトはなくなるよ。こうして成立した黒人多数派政権は国名を<strong class=\"source-bold\">ジンバブエ共和国</strong>に変えたんだ。さすがに、帝国主義者セシル＝ローズの名前はイヤでしょ。「ジンバブエ」って<strong class=\"source-bold\">古代の黒人が残した石造遺跡</strong>の名前からとった国名だね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 冷戦終結で国際情勢が変化し、南アフリカもアパルトヘイトを撤廃！</strong></span></h4>\n<p>じゃあ、南アフリカに戻るよ。1970年代になっても南アフリカの黒人暴動は続き、1976年の<strong class=\"source-bold\">ソウェト<ruby>蜂起<rt>ほうき</rt></ruby></strong>では、首都近郊の最大の黒人居住区で起きたデモを武装警官が弾圧、500名以上の死者を出した。さらに、ボタ大統領は白人、カラード（混血）、インド人（アジア系）からなる人種別三院制議会をつくったけれど、<strong class=\"source-bold\">黒人には一切公民権を認めなかった</strong>。</p>\n<p>そんな南アフリカにも変化が起きるよ。1980年代後半には世界各地で民主化運動</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "474": "<h2>474</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第25回</strong></span> 戦後の西アジア・アフリカ</p></blockquote>\n<p>が起こり、1989年には<strong class=\"source-bold\"><ruby>冷戦<rt>れいせん</rt></ruby>が終結する</strong>よね。この影響で<strong class=\"source-bold\">南アフリカへの国際的な非難</strong>が強まり、<strong class=\"source-bold\">デクラーク</strong>大統領は黒人との対話を進めたよ。1990年になると、南アフリカが不法に<ruby>占領<rt>せんりょう</rt></ruby>していた黒人国家<strong class=\"source-bold\">ナミビアの独立</strong>を認め、さらに<strong class=\"source-bold\">アフリカ民族会議【ANC】を合法化</strong>すると<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マンデラ</strong></span>も釈放し、1991年ついに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アパルトヘイトの法的<ruby>撤廃<rt>てっぱい</rt></ruby></strong></span>を実現した。</p>\n<p>そして、1994年に<strong class=\"source-bold\">初めて黒人に平等な選挙権が認められた</strong>結果、ANC が第1党となり、<strong class=\"source-bold\">マンデラが初の黒人大統領</strong>になったんだ。この政権ではデクラークも副大統領となって、白人も含めた国民統合政府ができたよ。その後も<strong class=\"source-bold\">南アフリカでは黒人大統領が続いている</strong>（ムベキ政権［1999〜2008］など）。2010年にサッカーのワールドカップが開かれたり、経済的には発展しているけど、<ruby>貧富<rt>ひんぷ</rt></ruby>格差（白人の<ruby>貧困<rt>ひんこん</rt></ruby>層の問題もあるんだ……）や治安の問題など、課題も多いね。</p>\n<blockquote><p>アパルトヘイトがなくなったのは、ソ連の崩壊と同じ年だ！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 現代でも頻発するアフリカの地域紛争……解決の道筋は？</strong></span></h4>\n<p>それじゃあ最後に、冷戦終結後に起きた内戦について見ておこう。</p>\n<p>まずは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ルワンダ内戦</strong></span>だよ。ベルギーが支配していたルワンダでは、<strong class=\"source-bold\">ベルギー</strong>が支配層として優遇した<strong class=\"source-bold\">少数派のツチ族</strong>が、<strong class=\"source-bold\">多数派のフツ族</strong>と対立していた。1973年、クーデタで<strong class=\"source-bold\">フツ族が政権</strong>を握ると、<ruby>弾圧<rt>だんあつ</rt></ruby>を恐れたツチ族は難民として国外に逃亡した。隣国のウガンダに逃げたツチ族はルワンダ愛国戦線を結成し、ツチ族が政権を握るウガンダ政府の支援を受けて帰国を目指したんだ。こうして1990年、<strong class=\"source-bold\">ルワンダ内戦が<ruby>勃発<rt>ぼっぱつ</rt></ruby></strong>した。1993年に和平に合意したものの、1994年に<strong class=\"source-bold\">フツ族の大統領が暗殺</strong>されたのをきっかけに、フツ族によるツチ族の大<ruby>虐殺<rt>ぎゃくさつ</rt></ruby>が起こり（一説には80万人）、再び内戦に逆戻りした。その後、首都を制圧した<strong class=\"source-bold\">ツチ族が政権</strong>を握って、内戦はひとまず終わったんだ。ただ、<ruby>報復<rt>ほうふく</rt></ruby>を恐れたフツ族が国外に逃亡したから、今度はフツ族難民が発生したんだね。</p>\n<p>その後、国連などの支援を受けて復興が始まると、内戦時代に<ruby>亡命<rt>ぼうめい</rt></ruby>したツチ族難民およそ200万人が帰国したよ。彼らが亡命中に海外で身につけた技術が、現在のルワンダの近代化を支えているんだ！</p>\n<blockquote><p>ベルギーが作ったツチ族とフツ族の対立が内戦の原因なんだよ……</p></blockquote>\n<p>もう一つが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソマリア内戦</strong></span>なんだけど、状況はかなりひどかった……。ソマリアでは、一党独裁政権のもとで複数の反政府ゲリラ組織が政府を攻撃していたんだけど、1991年に<strong class=\"source-bold\">一党<ruby>独裁<rt>どくさい</rt></ruby>政権が崩壊</strong>すると、各地で武装ゲリラが<ruby>割拠<rt>かっきょ</rt></ruby>し、もはや誰が権力を握っていて、誰が敵で誰が味方かわからないような無政府状態になって</p>",
  "475": "<h2>475</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後のアフリカ</u></p></blockquote>\n<p>しまった。この内戦で多くの難民が発生して、約400万人が<ruby>飢餓<rt>きが</rt></ruby>状態にあるといわれているよ。国連も内戦の終結のために動き、<strong class=\"source-bold\"><ruby>安保理<rt>あんぽり</rt></ruby>の決議に基づいてアメリカ軍中心の多国籍軍が<ruby>介入<rt>かいにゅう</rt></ruby></strong>したんだけど、国連内の<strong class=\"source-bold\">パキスタン兵の殺害</strong>をはじめ、あまりに多くの犠牲者を出したため、<strong class=\"source-bold\">多国籍軍が撤退</strong>したんだ！。その後、何度も<ruby>暫定<rt>ざんてい</rt></ruby>政権がつくられたんだけどそのたびに<ruby>潰<rt>つぶ</rt></ruby>され、隣国の<strong class=\"source-bold\">エチオピアやスーダンも介入</strong>して一時は泥沼化したけど、2012年には正式に外国からも承認された政府ができた。これ以後は、国連などが治安維持を指導しながら<ruby>平和裡<rt>へいわり</rt></ruby>に大統領選挙がおこなわれるなど、秩序はかなり回復しているよ。このまま平和が続けばいいね。</p>\n<p>じゃあ、今回はこれでおしまい。最後に年号 check！</p>\n<h4><span data-source-border=\"pink\" data-source-border-pattern=\"diagonal-lines\" data-source-corner-decoration=\"brown-triangles\" style=\"border:4px solid #f0a0a0;border-image:repeating-linear-gradient(135deg,#fff 0 3px,#f0a0a0 3px 4px) 4;padding:0 0.2em\"><span data-source-color=\"green\" data-source-outline-color=\"black\" style=\"color:#859476;text-shadow:1px 0 #001000,-1px 0 #001000,0 1px #001000,0 -1px #001000\"><strong class=\"source-bold\">‼</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><span data-source-color=\"red\" data-source-background=\"white\" data-source-border-shape=\"circle\" style=\"color:#e52715;background-color:#fff;border-radius:50%;padding:0 0.1em\"><strong class=\"source-red-bold\">年</strong></span><span data-source-color=\"red\" data-source-background=\"white\" data-source-border-shape=\"circle\" style=\"color:#e52715;background-color:#fff;border-radius:50%;padding:0 0.1em\"><strong class=\"source-red-bold\">号</strong></span>のツボ</span></span></h4>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">●</strong></span> <strong class=\"source-bold\">第1次中東戦争（イスラエル建国）</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1948</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>よ<rt>4</rt></ruby><ruby>果<rt>8</rt></ruby></strong></span>てまで シオンの丘へ）</p>\n<p>←シオンの丘は「シオニズム」の語源で、イェルサレムにある丘だ。「神の都」を象徴する言葉で、イスラエル建国の原点だ！</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">●</strong></span> <strong class=\"source-bold\">第2次中東戦争【スエズ戦争】</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1956</strong></span>］（ナセルが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>こ<rt>5</rt></ruby><ruby>ろ<rt>6</rt></ruby></strong></span> 国有化）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">●</strong></span> <strong class=\"source-bold\">アフリカの年</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1960</strong></span>］（アフリカ独立 <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby><ruby>苦<rt>9</rt></ruby><ruby>労<rt>60</rt></ruby><rt data-source-position=\"below\">クロオ</rt></ruby></strong></span>）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">●</strong></span> <strong class=\"source-bold\">第3次中東戦争</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1967</strong></span>］（ナセルと<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>組<rt>9</rt></ruby><ruby>む<rt>6</rt></ruby><ruby>な<rt>7</rt></ruby></strong></span> 奇襲がくるぞ）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">●</strong></span> <strong class=\"source-bold\">第4次中東戦争（第1次石油危機）</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1973</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>な<rt>7</rt></ruby><ruby>港<rt>3</rt></ruby></strong></span>に 石油ない）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">●</strong></span> <strong class=\"source-bold\">イラン革命</strong>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1979</strong></span>］（アッラー信じて <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>人<rt>1</rt></ruby></strong></span>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>苦<rt>9</rt></ruby></strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>な<rt>7</rt></ruby><ruby>く<rt>9</rt></ruby></strong></span>せ）</p></blockquote>\n<p>さあ、残すところ、あと1回！ 次回はいよいよ最終回、<strong class=\"source-bold\">冷戦終結後の世界</strong>だよ。ラストスパートだ。<ruby>頑張<rt>がんば</rt></ruby>れ〜。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>"
};

